CLAIMS = [
 (909,"technique-relevance","攻击者通过正常服务控制路径停止业务服务可造成独立可用性损失；安全工具和恢复服务分别由防御损伤与恢复抑制对象负责。","An adversary stopping a business service through its normal control path can cause independent availability loss; security and recovery services belong to defensive impairment and recovery inhibition respectively.",["NJT-0185"],["REF-000864","REF-000865","REF-000871"],"directly-observed","high"),
 (910,"mechanism-mapping","有序服务停止与批准维护共享停止待定至停止的终态序列，使仅看状态的分析难以从终态判断恶意控制者；进程、账户、权限与审批仍可恢复差分。","An orderly service stop shares the stop-pending to stopped terminal sequence with approved maintenance, making a state-only analysis unable to identify malicious control from the terminal state; process, account, authority, and approval can recover the difference.",["NJT-0185","NM-FD"],["REF-000866","REF-000867","REF-000336"],"strongly-inferred","medium"),
 (911,"detection","业务服务停止检测需要把控制进程或 API 调用者、服务状态、业务健康和维护审批按设备、服务与时间关联；只检测 net.exe 会遗漏其他路径。","Business-service stop detection needs to join controller process or API caller, service state, business health, and maintenance approval by device, service, and time; detecting only net.exe misses other paths.",["NJT-0185","DET-000213"],["REF-000868","REF-000598","REF-000869"],"strongly-inferred","high"),
 (912,"technique-boundary","恢复点、备份、恢复目录或恢复依赖的损失改变未来恢复能力，区别于 NJT-0156 当前数据销毁和 NJT-0157 当前数据加密。","Loss of recovery points, backups, recovery catalogs, or recovery dependencies changes future recoverability and is distinct from current-data destruction in NJT-0156 and current-data encryption in NJT-0157.",["NJT-0186"],["REF-000872","REF-000873","REF-000881"],"directly-observed","high"),
 (913,"mechanism-mapping","恢复平面可以在生产业务仍运行时失去副本或依赖，使生产监控暂时看似正常而后续恢复风险已增加；独立恢复清单和演练才能观察该差分。","The recovery plane can lose copies or dependencies while production continues, leaving production monitoring temporarily normal as future recovery risk rises; an independent recovery inventory and exercises are needed to observe the difference.",["NJT-0186","NM-BT"],["REF-000878","REF-000879","REF-000880"],"strongly-inferred","medium"),
 (914,"subtechnique-existence","恢复生命周期策略可以先写入缩短保留期，再由备份服务按计算到期时间删除恢复点，使原始策略主体与后来删除结果分离。","A recovery lifecycle policy can first shorten retention and later cause the backup service to delete recovery points at a calculated expiry, separating the policy writer from the deletion outcome.",["NJT-0186","NJS-0186-001","NM-BT"],["REF-000875","REF-000876","REF-000878"],"strongly-inferred","medium"),
 (915,"detection","恢复抑制分析应分别验证 Windows 恢复状态差和云恢复点生命周期、对象、主体及 RPO 结果；命令或策略变更本身只证明企图或前期风险。","Recovery-inhibition analytics separately verify Windows recovery-state differences and cloud recovery-point lifecycle, object, principal, and RPO outcomes; a command or policy change alone establishes attempt or pre-impact risk only.",["NJT-0186","NJS-0186-001","DET-000214"],["REF-000869","REF-000598","REF-000874","REF-000875","REF-000876","REF-000524"],"strongly-inferred","high"),
 (916,"mitigation","不同权的恢复管理、不可变保管库和完整恢复演练可限制直接删除与保留期缩短，但恢复点存在本身不证明依赖完整或能够恢复。","Differently authorized recovery administration, immutable vaults, and full restore exercises constrain direct deletion and retention shortening, while recovery-point presence alone does not prove dependencies are complete or restoration will succeed.",["NJT-0186","NJS-0186-001"],["REF-000877","REF-000878","REF-000879","REF-000880"],"strongly-inferred","high"),
 (917,"technique-relevance","攻击者使组织身份或系统界面实际呈现未经授权内容会直接损害展示完整性；内部或外部位置只是受众维度。","An adversary causing unauthorized content to be actually presented under an organization identity or system interface directly harms display integrity; internal or external location is only an audience dimension.",["NJT-0187"],["REF-000882"],"directly-observed","high"),
 (918,"technique-boundary","篡改展示内容以人类可见输出为直接对象；改变业务数据值影响流程或决策属于 T1565，网站入侵而无可见结果不满足本技术。","Defacement has human-visible output as its direct object; changing business data values to affect process or decision belongs to T1565, and website compromise without visible output does not satisfy this technique.",["NJT-0187"],["REF-000882","REF-000883","REF-000029"],"strongly-inferred","high"),
 (919,"subtechnique-existence","Hushmail 事件中域名解析被改向攻击者服务器并显示篡改页面，而规范源服务器未被未授权访问，证明展示源绑定替换可让源站完整性观察与用户结果分离。","In the Hushmail incident, domain resolution was redirected to an attacker server that displayed a defaced page while the canonical origin was not accessed without authorization, establishing that display-source binding substitution can separate origin-integrity observation from user outcome.",["NJT-0187","NJS-0187-001","NM-BT"],["REF-000884","REF-000885"],"directly-observed","high"),
 (920,"detection","展示完整性检测需连接批准发布状态、多个观察点的 DNS 答案、TLS/HTTP 内容和实际视觉结果；只有记录变化或 IP 变化不能确认篡改。","Display-integrity detection must join approved publication state, DNS answers from multiple vantages, TLS/HTTP content, and actual visual outcome; a record or IP change alone cannot confirm defacement.",["NJT-0187","NJS-0187-001","DET-000215"],["REF-000887","REF-000888","REF-000889","REF-000890"],"strongly-inferred","high"),
 (921,"technique-relevance","未授权破坏硬件消费的非易失固件可使设备不能启动或初始化；必须区别于仍执行恶意代码的 pre-OS 植入和磁盘结构擦除。","Unauthorized damage to hardware-consumed nonvolatile firmware can prevent boot or initialization and must be distinguished from a pre-OS implant that still executes adversary code and from disk-structure wiping.",["NJT-0188"],["REF-000891","REF-000892","REF-000194","REF-000898"],"directly-observed","high"),
 (922,"mechanism-mapping","固件破坏在 OS、agent 与常规读回启动前使设备失效，截断同一设备对写入者、固件差分和根因的在带观察；明显停机不等于根因可见。","Firmware corruption can disable a device before its OS, agent, and ordinary readback start, truncating the same device's in-band observation of writer, firmware difference, and root cause; a conspicuous outage does not make the root cause visible.",["NJT-0188","NM-DO"],["REF-000892","REF-000194","REF-000897"],"strongly-inferred","medium"),
 (923,"detection","固件破坏检测需要连接刷写进程与驱动、固件资源状态、重启、远程证明、外部 POST/心跳失败及离线恢复读回，单个固件更新错误不能确认攻击。","Firmware-corruption detection needs to join flashing process and driver, firmware-resource status, reboot, remote attestation, external POST or heartbeat failure, and offline recovery readback; one firmware-update error cannot confirm attack.",["NJT-0188","DET-000216"],["REF-000893","REF-000894","REF-000895","REF-000896","REF-000897","REF-000366"],"strongly-inferred","high"),
 (924,"mitigation","硬件写保护、完整测量、可信固件源和独立恢复根可限制固件破坏并保留根因证据，但未测量组件、同权 BMC 和旧设备会留下盲区。","Hardware write protection, complete measurement, trusted firmware sources, and an independent recovery root constrain corruption and preserve root-cause evidence, while unmeasured components, a similarly authorized BMC, and legacy devices leave blind spots.",["NJT-0188"],["REF-000194","REF-000894","REF-000895","REF-000897"],"strongly-inferred","high"),
 (925,"technique-relevance","资源劫持要求攻击者实际使用受害方计算、网络、消息或托管服务完成自身任务，并产生可计量用量、费用、配额或容量影响；执行和凭据只是前置。","Resource Hijacking requires actual adversary use of victim compute, network, messaging, or managed-service capacity for an adversary task with metered usage, cost, quota, or capacity effect; execution and credentials are precursors.",["NJT-0189"],["REF-000899","REF-000910"],"directly-observed","high"),
 (926,"subtechnique-existence","Microsoft 观察到矿工依据用户空闲和 GPU 竞争负载停止与重启，使消费集中在剩余容量窗口并削弱持续高负载与用户卡顿信号。","Microsoft observed a miner stopping and restarting according to user idle state and competing GPU load, concentrating consumption in residual-capacity windows and weakening sustained-high-load and user-slowdown signals.",["NJT-0189","NJS-0189-001","NM-ST"],["REF-000900","REF-000906","REF-000907"],"directly-observed","high"),
 (927,"subtechnique-existence","消息或模型请求可让提供方在受害账户下执行和计量实际工作，使主机端没有对应消费者进程；主体、请求、令牌/消息和费用仍可在服务日志关联。","Messaging or model requests can cause a provider to execute and meter actual work under a victim account without a corresponding consumer process on the victim host; principal, request, tokens or messages, and cost remain correlatable in service logs.",["NJT-0189","NJS-0189-002","NM-BT"],["REF-000901","REF-000902","REF-000903","REF-000904"],"strongly-inferred","medium"),
 (928,"detection","活动门控资源消耗检测需要把进程、资源计数、用户活动切换和网络目的按分钟与长期窗口关联；只设持续高 CPU 阈值会遗漏闭环暂停。","Detection of activity-gated consumption needs to join processes, resource counters, user-activity transitions, and network destinations across minute and long horizons; a sustained-high-CPU threshold misses closed-loop pausing.",["NJT-0189","NJS-0189-001","DET-000217"],["REF-000598","REF-000604","REF-000905","REF-000906"],"strongly-inferred","high"),
 (929,"detection","提供方计量消费检测必须使用服务事务字段和 owner/用途基线；账单异常是延迟支持信号，不能替代实际模型或消息交易。","Provider-metered consumption detection requires service-transaction fields and owner/purpose baselines; billing anomaly is delayed supporting evidence and cannot replace actual model or messaging transactions.",["NJT-0189","NJS-0189-002","DET-000218"],["REF-000903","REF-000904","REF-000908","REF-000909","REF-000524"],"strongly-inferred","high"),
 (930,"mitigation","资源 owner、每主体限额、独立计量、端点消费者控制和提供方事务准入可限制资源劫持收益，但低速滥用、被盗批准身份和延迟账单仍会造成残余风险。","Resource owners, per-principal limits, independent metering, endpoint consumer controls, and provider transaction admission constrain Resource Hijacking yield, while low-rate abuse, stolen approved identities, and delayed billing leave residual risk.",["NJT-0189","NJS-0189-001","NJS-0189-002"],["REF-000900","REF-000902","REF-000903","REF-000908"],"strongly-inferred","high"),
]

