def mechanism(ref, role, summary, analysis, refs, confidence):
    return {"mechanism_ref":ref,"role":role,"summary":summary,"analysis":analysis,"evidence_refs":refs,"confidence":confidence}
def context(scenario, attacker, defender):
    return {"application_scenarios":scenario,"threat_model":{"attacker_model":attacker,"defender_model":defender}}
def defense(strategies, mitigations):
    return {"detections":{"coverage":"available","strategy_refs":strategies},"mitigations":{"coverage":"available","mitigation_refs":mitigations}}


T1489_DIR="matrix/tactics/TA0040-impact/techniques/NJT-0185-business-service-stop"
write(f"{T1489_DIR}/technique.yaml", {
 "schema_version":"2.0.0","type":"technique","id":"NJT-0185","name":B("业务服务停用","Business Service Stop"),
 "summary":B("攻击者通过服务接受的正常控制路径有序停止业务服务，使合法功能中断并让恶意停用呈现常规管理终态。","Adversaries orderly stop business services through accepted control paths, interrupting legitimate functionality while giving malicious disablement an ordinary administrative terminal state."),
 "aliases":["Service Stop","T1489"],
 "classification":{"tactic_refs":["TA0040"],"origin":{"kind":"attack-adapted","source_attack_id":"T1489","source_attack_version":"19.1"},"decision_ref":"DEC-TA0040-T1489"},
 "definition_and_concept":PP(
  ("业务服务停用是攻击者使数据库、消息、Web、工业应用、文件共享、虚拟化工作负载或其他业务功能从运行状态转为停止、禁用或不能继续服务合法用户。直接对象是服务可用性与消费结果；管理命令、API、进程终止形式、服务名称和平台只是实现。服务仍登记、底层数据仍存在或主机仍运行，都不否定业务可用性损失。","Business Service Stop moves a database, messaging, Web, industrial application, file-sharing, virtualization workload, or another business function from running to stopped, disabled, or unable to serve legitimate users. The direct object is service availability and its consumer outcome. Management commands, APIs, process-termination form, service name, and platform are implementations. A registered service, surviving data, or a running host does not negate business availability loss."),
  ("Niji 的正式范围要求有证据的观察差异：攻击者让服务管理器转交标准停止请求，服务按自身状态机清理并报告常规停止终态。恶意意图不编码在终态，防守方必须把控制者、权限、命令或 API、维护审批和业务结果重新连接。异常崩溃、资源耗尽和公开批量杀进程不在这一适配范围。","Niji formal scope requires an evidenced observation difference. The adversary has a service manager deliver a standard stop request, and the service cleans up through its own state machine and reports an ordinary stopped terminal state. Malicious intent is absent from that terminal state, so defenders must reconnect controller, authority, command or API, maintenance approval, and business outcome. Abnormal crashes, resource exhaustion, and overt mass process killing fall outside this adapted scope.")),
 "stealth_characteristics":PP(
  ("业务服务停用把控制意图与状态结果分离。Windows SCM 接受停止控制后，服务从运行态经过停止待定进入停止态，同一序列也用于正常维护；只消费服务状态或健康面板的防守方看到熟悉的“已停止”，不会自动得知恶意主体或后继加密目的。相比异常终止，有序停止还移除崩溃或失败这一类区分特征。","Business Service Stop separates control intent from state outcome. After Windows SCM accepts a stop control, the service moves from running through stop-pending to stopped, the same sequence used for maintenance. A defender consuming only service state or a health panel sees a familiar stopped result without the malicious principal or later encryption purpose. Compared with abnormal termination, orderly stopping also removes crash or failure as a distinguishing feature."),
  ("残余痕迹包括控制进程及命令行、账户与登录会话、服务句柄权限、SCM 状态、启动类型、依赖服务、维护单据缺口、外部业务健康失败及后继文件活动。直接 API 调用可能没有 net/sc 包装器，但调用进程、服务访问和不同权健康探针仍能恢复因果。","Residual traces include controller process and command line, account and logon session, service-handle authority, SCM state, start type, dependencies, absent maintenance ticket, external health failure, and successor file activity. A direct API call may omit a net or sc wrapper, but caller process, service access, and a differently authorized health probe can still restore causality.")),
 "scope_boundary_definition":PP(
  ("纳入攻击者通过业务服务接受的管理路径实施停止或禁用，并实际使组织预期功能不可用的行为。服务处于 stopped 状态本身不足；还需目标业务职责、控制主体或进程、未经批准上下文和健康/用户结果。补丁、升级、故障转移、容量维护、排障、依赖编排、崩溃恢复和许可证问题是强反例。","Include an adversary stop or disablement through the accepted management path of a business service that actually makes an expected organizational function unavailable. A stopped state alone is insufficient; target business role, controlling principal or process, missing approval, and health or user outcome are also required. Patching, upgrade, failover, capacity maintenance, troubleshooting, dependency orchestration, crash recovery, and licensing issues are strong counterexamples."),
  ("安全产品、日志代理或响应服务被停用且直接削弱防御时归 NJT-0123；备份、快照和恢复服务被停用且直接损害恢复能力时归 NJT-0186。整机或虚拟机关机/重启归 T1529。停止服务为后继加密或销毁释放文件锁可以共同记录，但内容结果分别归 NJT-0157 和 NJT-0156。","Stopping a security product, logging agent, or response service belongs to NJT-0123 when it directly impairs defense. Stopping backup, snapshot, or recovery services belongs to NJT-0186 when it directly harms recovery. Whole-host or VM shutdown and reboot belongs to T1529. A service stop that releases locks for later encryption or destruction can be co-recorded, while content outcomes belong to NJT-0157 and NJT-0156 respectively.")),
 "application_scenarios_and_threat_model":context(
  P("在勒索或破坏的数据处理阶段前，攻击者可用已取得的管理员会话、远程管理通道或载荷内服务 API，有序停止 MSSQL、Exchange、Web 应用或虚拟化相关业务服务。停止立即中断合法业务，也可能释放应用持有的数据文件。Prestige 的硬编码 `net.exe stop MSSQLSERVER` 展示了这一链，但服务损失和后继密文必须分别证明。","Before the data-processing stage of ransomware or destruction, an adversary can use an acquired administrator session, remote management path, or an in-payload service API to orderly stop MSSQL, Exchange, a Web application, or a virtualization-related business service. The stop immediately interrupts business and may release application-held files. Prestige's hard-coded `net.exe stop MSSQLSERVER` demonstrates the chain, while service loss and later ciphertext require separate proof."),
  P("攻击者需要目标服务的停止或等价控制权限、服务和依赖知识，以及承受停机暴露行动的能力。命令包装器方便自动化但留下参数；直接 API 减少包装器，却仍有调用进程和服务句柄。受保护 DACL、不可停止服务、集群仲裁、快速故障转移和不同权审批会限制效果。","The attacker needs stop or equivalent control authority, service and dependency knowledge, and tolerance for the outage exposing the operation. Command wrappers ease automation but leave arguments; direct APIs remove the wrapper while retaining a caller process and service handle. Protected DACLs, non-stoppable services, cluster quorum, rapid failover, and differently authorized approval constrain the effect."),
  P("防守方保存服务清单及 owner、SCM 状态、进程与命令行、账户/会话、远程来源、服务权限、维护审批和独立业务健康探针，并按设备、服务、主体和时间关联。仅看当前状态无法判断操作者，限于 net/sc 会遗漏 PowerShell、WMI 与直接 API，只有本地 agent 时还可能与服务一起失去观察。","Defenders retain service inventory and owner, SCM state, process and command line, account and session, remote origin, service authority, maintenance approval, and an independent business-health probe and correlate by device, service, principal, and time. Current state cannot identify the operator, net/sc-only detection misses PowerShell, WMI, and direct APIs, and a local-only agent may lose observation together with the service.")),
 "stealth_mechanisms":[mechanism("NM-FD","primary",B("有序停止让恶意中断呈现常规管理终态","Orderly stopping gives malicious interruption an ordinary administrative terminal state"),P("攻击者经服务管理器发送服务已声明接受的停止控制，服务执行自身清理并报告停止待定和停止终态；痕迹从异常崩溃变为正常管理也会产生的状态序列。只消费状态的守方难以从终态区分恶意与维护，形成特征伪装；调用者、权限、审批与独立健康结果仍能揭示矛盾。","The adversary sends a stop control accepted by the service through the service manager, and the service performs cleanup and reports stop-pending and stopped states. The trace changes from an abnormal crash to a sequence also produced by normal administration. State-only defenders cannot distinguish maliciousness from maintenance at the terminal state, producing feature disguise; caller, authority, approval, and independent health outcome reveal the contradiction."),["REF-000865","REF-000866","REF-000867","REF-000336"],"medium")],
 "subtechnique_taxonomy":{"narrative":PP(("开放搜索只确认有序控制路径这一稳定匿迹变量，它同时定义适配后的父级范围，若再建唯一子项会与父级同义。命令包装器、平台、服务类别、停止数量、启动类型和后继载荷是实现、持续时间或相邻结果。","Open search confirms only the orderly control path as a stable stealth variable, and it also defines the adapted parent scope; creating it as the sole child would duplicate the parent. Command wrapper, platform, service type, stop count, start type, and successor payload are implementations, duration, or adjacent outcomes."),("维护窗口对齐、跨主机交错和低速停止缺少结论级攻击证据，保持 deferred；安全和恢复服务的选择由 NJT-0123 与 NJT-0186 负责。未来子项需另有可控变量、痕迹变化和不可互换防御。","Maintenance-window alignment, cross-host staggering, and low-rate stopping lack conclusion-level attack evidence and remain deferred. NJT-0123 and NJT-0186 own selection of security and recovery services. A future child needs another controllable variable, trace change, and non-interchangeable defense.")),"coverage":"none-justified","subtechnique_refs":[]},
 "defense":defense(["DET-000213"],["MIT-000194"]),
 "evidence":{"claim_refs":["CLM-000909","CLM-000910","CLM-000911"],"case_refs":["CASE-000267"],"reference_refs":["REF-000864","REF-000865","REF-000866","REF-000867","REF-000868","REF-000869","REF-000870","REF-000871","REF-000336","REF-000598"]},
 "research":{"limitations":PP(("Prestige 直接证明攻击者用标准命令停止 MSSQL 服务，Windows 文档证明正常状态机，但事件报告把停止归于释放锁和提高加密可靠性，没有陈述维护式伪装动机。因此父行为置信度高，匿迹机理为中等，不能把所有有序停止解释为隐蔽。","Prestige directly establishes an attacker stopping MSSQL with a standard command, and Windows documentation establishes the normal state machine. The incident attributes stopping to lock release and encryption reliability rather than maintenance camouflage. Parent behavior is high confidence while the stealth mechanism is medium, and not every orderly stop is covert."),("服务状态和业务故障有大量正常原因；缺少调用者、权限、审批或独立健康结果时只能报告未经解释的停止。部分平台不会提供等价 SCM 字段，正式分析必须降低置信度而不能伪造字段。","Service state and business failure have many benign causes. Without caller, authority, approval, or independent health outcome, only an unexplained stop can be reported. Some platforms lack equivalent SCM fields; deployment must lower confidence rather than invent fields."))},"lifecycle":life()})

T1490_DIR="matrix/tactics/TA0040-impact/techniques/NJT-0186-inhibit-system-recovery"
write(f"{T1490_DIR}/technique.yaml", {
 "schema_version":"2.0.0","type":"technique","id":"NJT-0186","name":B("抑制系统恢复","Inhibit System Recovery"),
 "summary":B("攻击者削减恢复点、备份或恢复依赖，使生产业务可能仍运行而未来恢复能力已不可见地下降。","Adversaries reduce recovery points, backups, or dependencies so production may still run while future recoverability has already declined outside ordinary production observation."),"aliases":["T1490"],
 "classification":{"tactic_refs":["TA0040"],"origin":{"kind":"attack-adapted","source_attack_id":"T1490","source_attack_version":"19.1"},"decision_ref":"DEC-TA0040-T1490"},
 "definition_and_concept":PP(("抑制系统恢复是攻击者删除、禁用或重配置卷影副本、备份、快照、恢复目录、恢复密钥、启动恢复和恢复服务，使受影响资产不能按既定 RPO/RTO 回到可信业务状态。直接对象是恢复职责及可恢复性结果，而不是当前生产数据是否已经被删除或加密。","Inhibit System Recovery deletes, disables, or reconfigures shadow copies, backups, snapshots, recovery catalogs, recovery keys, boot recovery, or recovery services so an affected asset cannot return to a trusted business state under its intended RPO and RTO. The direct object is the recovery role and recoverability outcome rather than whether current production data has already been deleted or encrypted."),("Niji 关注恢复平面与生产平面的观察错位。恢复副本可以先被删除，或保留策略先被缩短，而生产系统继续服务；常规业务健康面因此看似正常，直到后续破坏或恢复请求才暴露风险。直接破坏和延迟策略都属于父级，只有后者具有足够独立的执行主体、时间和防御差异而形成原生子项。","Niji focuses on the observation mismatch between recovery and production planes. Recovery copies can be deleted or retention shortened while production continues serving, so ordinary business-health views remain normal until later destruction or a restore request exposes the risk. Direct destruction and deferred policy action belong to the parent, while only the latter has sufficiently distinct execution actor, time, and defense to form a native child.")),
 "stealth_characteristics":PP(("恢复抑制的影响常在当前业务之外积累：生产文件、服务和用户会话尚未变化，恢复点数量、保留期限、密钥或恢复依赖已被削弱。只监控生产可用性和端点告警的守方缺少恢复平面状态，不会立刻看见未来不可恢复性。直接删除留下密集命令/API，策略驱动到期则把策略主体与服务删除结果分离。","Recovery-inhibition impact often accumulates outside current business operation. Production files, services, and sessions may be unchanged while recovery-point count, retention, keys, or dependencies have weakened. Defenders watching only production availability and endpoint alerts lack recovery-plane state and do not immediately see future non-recoverability. Direct deletion leaves concentrated commands or APIs, while policy-driven expiry separates the policy actor from service deletion outcomes."),("残余痕迹包括恢复控制命令与进程、备份 API 主体、恢复点和 vault 标识、策略前后态、计算到期时间、锁状态、RPO 覆盖差及恢复演练结果。恢复清单、不同权控制面与完整演练能恢复差分；只有恢复点“存在”不能证明依赖或密钥完整。","Residual traces include recovery-control commands and processes, backup API principal, recovery-point and vault identifiers, policy before and after state, calculated expiry, lock state, RPO coverage gap, and restore-test result. Recovery inventory, differently authorized control planes, and full exercises recover the differential. Mere recovery-point presence does not prove dependencies or keys are intact.")),
 "scope_boundary_definition":PP(("纳入攻击者控制的恢复对象或依赖状态下降，并能证明受保护资源的可恢复性、RPO 或恢复测试结果受损。命令、API 或策略变更未成功、恢复对象仍满足要求时只表示企图或暴露。已批准保留调整、灾备演练、资源退役、容量清理、备份迁移和故障修复是反例。","Include adversary-controlled reduction in recovery-object or dependency state with proven damage to protected-resource recoverability, RPO, or restore-test outcome. An unsuccessful command, API, or policy change where recovery requirements remain met establishes attempt or exposure only. Approved retention changes, DR exercises, resource retirement, capacity cleanup, backup migration, and fault repair are counterexamples."),("当前业务文件或对象被删除/覆写归 NJT-0156，被加密归 NJT-0157；停止普通业务服务归 NJT-0185。停止或篡改备份产品只有在直接损害恢复能力时进入本项；如果直接结果是安全观察削弱，还要按 NJT-0123 评估。","Deletion or overwrite of current business files and objects belongs to NJT-0156, encryption to NJT-0157, and stopping an ordinary business service to NJT-0185. Stopping or changing backup products enters here only when recovery is directly impaired; a direct loss of security observation also requires assessment under NJT-0123.")),
 "application_scenarios_and_threat_model":context(P("勒索操作者可删除 Windows 卷影副本、禁用恢复环境和备份目录，或在云备份中删除恢复点、缩短保留期限及移除锁定。直接路径常紧邻加密；策略路径可在数小时或数日后由服务执行，使生产侧暂时无故障。","Ransomware operators can delete Windows shadow copies, disable recovery environments and catalogs, or delete cloud recovery points, shorten retention, and remove locks. Direct paths often precede encryption, while a policy path can execute through the service hours or days later with no immediate production failure."),P("攻击者需要本地主机恢复控制权、备份管理员/API 权限或改变生命周期和锁配置的云权限，并了解哪些副本覆盖关键资产。不可变合规锁、不同权账户、离线副本、最小权限和快速策略告警会限制效果；过早删除也会暴露行动。","The attacker needs local recovery-control authority, backup administrator or API rights, or cloud authority over lifecycle and lock configuration and knowledge of copies covering critical assets. Immutable compliance lock, differently authorized accounts, offline copies, least privilege, and rapid policy alerts constrain the effect; early deletion can also expose the operation."),P("防守方维护资产到恢复点、密钥、vault、RPO/RTO 和 owner 的映射，采集主机命令/状态、CloudTrail、策略版本、锁状态和删除结果，并执行受控恢复。若恢复管理与生产共享身份或日志、没有前态清单、只检查副本存在而不测试依赖，就会形成盲区。","Defenders maintain mappings from assets to recovery points, keys, vaults, RPO/RTO, and owners; collect host command and state, CloudTrail, policy revisions, lock state, and deletion outcomes; and perform controlled restores. Blind spots arise when recovery and production share identities or logs, prior-state inventory is absent, or defenders check only copy presence without testing dependencies.")),
 "stealth_mechanisms":[mechanism("NM-BT","primary",B("恢复能力先于生产故障在独立观察面中消失","Recovery capability disappears in a separate observation plane before production fails"),P("攻击者先削减恢复副本、策略或依赖，生产业务仍从当前数据运行；痕迹落在恢复控制面和清单，而日常业务面暂时没有故障。只观察生产的守方会把风险推迟到加密、销毁或恢复请求之后，形成行为透明；不同权恢复清单、策略差分和演练能提前揭示。","The adversary first reduces recovery copies, policy, or dependencies while production continues from current data. Traces remain in the recovery control plane and inventory while ordinary business shows no immediate failure. Production-only defenders defer discovery until encryption, destruction, or a restore request, producing behavioral transparency. Differently authorized recovery inventory, policy diffs, and exercises reveal it earlier."),["REF-000878","REF-000879","REF-000880","REF-000881"],"medium")],
 "subtechnique_taxonomy":{"narrative":PP(("策略驱动的延迟恢复点到期以攻击者改变保留策略、由服务在计算时间执行删除为变量；它把写入主体与删除主体、配置时点与影响时点分开，需要策略版本和恢复点结果的长窗口关联。直接命令/API 删除保持父级核心。","Deferred Policy-Driven Recovery-Point Expiry varies an attacker change to retention policy followed by service deletion at a calculated time. It separates policy writer from deletion actor and configuration time from impact time and requires long-horizon correlation between policy revision and recovery-point outcome. Direct command or API deletion remains parent core."),("恢复介质类型、Windows 与云平台、备份产品和快照格式不是子项边界。跨账户拓扑、诱饵恢复点、低速删除和伪造恢复成功缺少结论级证据，保持 deferred。","Recovery-media type, Windows versus cloud platform, backup product, and snapshot format do not define children. Cross-account topology, decoy recovery points, slow deletion, and forged restore success lack conclusion-level evidence and remain deferred.")),"coverage":"established","subtechnique_refs":["NJS-0186-001"]},
 "defense":defense(["DET-000214"],["MIT-000158","MIT-000195"]),"evidence":{"claim_refs":["CLM-000912","CLM-000913","CLM-000914","CLM-000915","CLM-000916"],"case_refs":["CASE-000268"],"reference_refs":["REF-000872","REF-000873","REF-000869","REF-000598","REF-000874","REF-000875","REF-000876","REF-000877","REF-000878","REF-000879","REF-000880","REF-000881","REF-000524"]},
 "research":{"limitations":PP(("公开事件充分证明攻击者删除卷影副本、恢复点和备份，生产/恢复分面亦有权威指导；生产继续运行只说明潜伏窗口，不证明所有攻击者主观寻求匿迹。恢复点存在也不等于可恢复，只有受控演练能验证依赖。","Public incidents establish adversary deletion of shadow copies, recovery points, and backups, and authoritative guidance supports production/recovery separation. Continued production creates a latent window but does not prove every adversary subjectively sought stealth. Recovery-point presence does not equal recoverability; controlled exercises are needed to validate dependencies."),("AWS 文档证明策略驱动自动到期与字段，Mandiant 证明需要监测该控制面，但没有命名受害者完成恶意策略写入到失败恢复的全链。子项保持中等置信且无 CASE，不能推广到字段和语义不同的其他产品。","AWS documents policy-driven automatic expiry and fields, and Mandiant establishes the need to monitor that plane, but no named victim completes malicious policy write through failed restore. The child remains medium confidence without a CASE and cannot be generalized to products with different fields and semantics."))},"lifecycle":life()})

write(f"{T1490_DIR}/subtechniques/NJS-0186-001-deferred-policy-driven-recovery-expiry/subtechnique.yaml", {
 "schema_version":"2.0.0","type":"evasion-subtechnique","id":"NJS-0186-001","parent_ref":"NJT-0186","name":B("策略驱动的延迟恢复点到期","Deferred Policy-Driven Recovery-Point Expiry"),"summary":B("攻击者缩短恢复点生命周期，让备份服务稍后自动删除恢复材料，使策略写入与损失事件分离。","An adversary shortens recovery-point lifecycle so a backup service later deletes recovery material automatically, separating the policy write from the loss event."),"aliases":[],"lineage":{"attck_subtechnique_inherited":False},
 "definition_and_concept":PP(("策略驱动的延迟恢复点到期是攻击者改变备份计划或恢复点生命周期，把保留期限缩短到低于受保护资产要求，并让备份服务在计算到期时间自动删除恢复点。分类变量是一次策略写入与后来服务执行在主体、时间和遥测平面上的分离，不是云产品或备份类型。","Deferred Policy-Driven Recovery-Point Expiry changes a backup plan or recovery-point lifecycle so retention falls below protected-asset requirements and a backup service automatically deletes the point at calculated expiry. The variable is separation of one policy write from later service execution across actor, time, and telemetry plane, not cloud product or backup type."),("子项只有在策略变化实际覆盖关键恢复点、服务到期结果出现且幸存恢复点造成 RPO 缺口时完成。缩短保留但被锁拒绝、及时回滚或尚未到期只证明企图或事前风险。","The child completes only when the policy change covers critical recovery points, service expiry occurs, and surviving points create an RPO gap. Shortened retention rejected by a lock, promptly rolled back, or not yet expired establishes an attempt or pre-impact risk only.")),
 "stealth_characteristics":PP(("策略驱动的延迟恢复点到期可以在删除前数小时或数日写入策略，后来结果由备份服务身份和调度产生；直接删除阈值看不到原操作者，生产业务也可能继续正常。只看当前恢复点或服务删除事件的守方会丢失策略因果。","Deferred Policy-Driven Recovery-Point Expiry can write policy hours or days before deletion, while later outcomes are produced under backup-service identity and scheduling; direct-deletion thresholds miss the original operator and production may continue normally. Defenders viewing only current recovery points or service deletion events lose policy causality."),("策略版本、DeleteAfterDays、CalculatedLifecycle DeleteAt、vault/恢复点 ARN、服务删除事件、资源映射和 RPO 差仍可串联。及时事前告警、不可变锁和长期日志会显著降低优势。","Policy revision, DeleteAfterDays, CalculatedLifecycle DeleteAt, vault and recovery-point ARNs, service deletion events, resource mapping, and RPO differential remain joinable. Prompt pre-impact alerting, immutable locks, and long retention materially reduce the advantage.")),
 "scope_boundary_definition":PP(("纳入未获批准的生命周期或备份计划变更，使关键恢复点在以后由服务删除并导致恢复覆盖低于要求。获批保留调整、资源退役、成本清理和测试 vault 是反例；配置变化没有实际结果时不确认。","Include an unapproved lifecycle or backup-plan change that later causes service deletion of critical recovery points and lowers recovery coverage below requirement. Approved retention changes, resource retirement, cost cleanup, and test vaults are counterexamples; a configuration change without outcome is not confirmed."),("直接 DeleteRecoveryPoint、删除卷影副本和禁用 WinRE 属于父级核心；当前业务对象的生命周期删除归 NJT-0156。其他平台只有具备等价策略、计算到期、服务结果和 RPO 证据才能纳入。","Direct DeleteRecoveryPoint, shadow-copy deletion, and WinRE disablement remain parent core; lifecycle deletion of current business objects belongs to NJT-0156. Other platforms enter only with equivalent policy, calculated expiry, service outcome, and RPO evidence.")),
 "application_scenarios_and_threat_model":context(P("取得 AWS Backup 管理权的攻击者可缩短 DeleteAfterDays、改变计划或选择，让现有/后继恢复点在服务计算的 DeleteAt 到期。若 SOC 只监测即时删除 API，策略事件与后来 BackupDeleted 可能跨值班窗口。","An attacker with AWS Backup authority can shorten DeleteAfterDays or change plans or selections so existing or later recovery points expire at the service-calculated DeleteAt. A SOC watching only immediate delete APIs may place policy and later BackupDeleted events in different shifts."),P("攻击者需要更新生命周期或计划的权限、目标 vault 与资源映射知识以及等待到期的时间。合规 Vault Lock、最低保留策略、不同权审批和及时回滚会阻断或缩小结果。","The attacker needs lifecycle or plan update authority, knowledge of target vault and resource mapping, and time to wait for expiry. Compliance Vault Lock, retention floors, differently authorized approval, and prompt rollback block or reduce the outcome."),P("防守方保留 CloudTrail、策略版本、恢复点清单、CalculatedLifecycle、vault 锁、资源映射和 RPO/RTO，并跨到期时间关联服务结果。缺少旧策略、跨账户副本或还原测试时，只能证明策略异常或清单损失，不能断言不可恢复。","Defenders retain CloudTrail, policy revisions, recovery-point inventory, CalculatedLifecycle, vault locks, resource mapping, and RPO/RTO and correlate service outcomes across expiry. Missing prior policy, cross-account copies, or restore tests means only policy anomaly or inventory loss can be established, not non-recoverability.")),
 "stealth_mechanisms":[mechanism("NM-BT","primary",B("服务到期把策略写入主体与恢复点删除结果分离","Service expiry separates the policy writer from recovery-point deletion outcomes"),P("攻击者先改变保留策略，服务随后按计算时间以自身身份删除恢复点；痕迹从一个即时主体—对象事务变为较早配置和较晚服务结果。只看删除事件的守方难以归因，跨策略版本、到期和资源覆盖关联能恢复链条。","The adversary changes retention policy first, and the service later deletes recovery points at the calculated time under its own identity. The trace changes from one immediate actor-object transaction to an earlier configuration and later service outcome. Delete-only defenders struggle to attribute the result, while correlation across policy revisions, expiry, and resource coverage restores the chain."),["REF-000875","REF-000876","REF-000878"],"medium")],
 "defense":defense(["DET-000214"],["MIT-000195"]),"evidence":{"claim_refs":["CLM-000914","CLM-000915","CLM-000916"],"case_refs":[],"reference_refs":["REF-000874","REF-000875","REF-000876","REF-000877","REF-000878","REF-000524"]},
 "research":{"limitations":PP(("官方资料建立可复现的策略—计算到期—服务删除链，防御资料也要求监控未授权保留变化；没有公开命名受害者案例证明攻击者实际用此路径造成失败恢复。正式置信度为中等且不创建 CASE。","Official sources establish a reproducible policy-to-calculated-expiry-to-service-deletion chain, and defensive guidance calls for monitoring unauthorized retention changes. No public named victim case establishes attacker use causing failed restoration. Confidence is medium and no CASE is created."),("服务删除时间、连续备份语义、锁模式和已有恢复点是否受新计划影响需按产品验证。短保留期、服务延迟和 RPO 缺口也可能由合法运营产生，必须连接主体、审批和结果。","Service deletion timing, continuous-backup semantics, lock mode, and whether a new plan affects existing points require product validation. Short retention, service delay, and an RPO gap can also arise from legitimate operations and require actor, approval, and outcome."))},"lifecycle":life()})

T1491_DIR="matrix/tactics/TA0040-impact/techniques/NJT-0187-defacement"
write(f"{T1491_DIR}/technique.yaml", {
 "schema_version":"2.0.0","type":"technique","id":"NJT-0187","name":B("篡改展示内容","Defacement"),"summary":B("攻击者恶意替换组织控制的视觉内容或界面结果，并通过把变化移出规范发布源而延迟发现与归因。","Adversaries maliciously replace organization-controlled visual content or interface output and delay detection and attribution by moving the change outside the canonical publication source."),"aliases":["T1491"],
 "classification":{"tactic_refs":["TA0040"],"origin":{"kind":"attack-adapted","source_attack_id":"T1491","source_attack_version":"19.1"},"decision_ref":"DEC-TA0040-T1491"},
 "definition_and_concept":PP(("篡改展示内容是攻击者让组织控制的网站、内部入口、登录消息、桌面或其他面向人的界面呈现未经授权的文字、图像或布局，以传递消息、恐吓、误导、施压或宣示入侵，直接损害展示完整性与受众信任。概念单位是组织身份或系统界面下实际呈现结果；文件、数据库、CMS、壁纸和 DNS 记录只是载体。","Defacement causes a website, internal portal, login message, desktop, or other human-facing interface controlled by an organization to present unauthorized text, imagery, or layout to communicate, intimidate, mislead, pressure, or claim intrusion, directly harming display integrity and audience trust. The conceptual unit is the result actually presented under the organization identity or interface; files, databases, CMS objects, wallpaper, and DNS records are carriers."),("Niji 关注展示结果与守方监测的规范发布源之间的观察差异。直接覆写页面或壁纸界定父行为但不自动构成匿迹；当攻击者保留规范源而替换标识到内容源的绑定时，源站完整性可继续显示正常，受众却取得攻击者页面。站点访问、Web shell 或不可见脚本若没有展示结果属于相邻行为。","Niji focuses on the observation difference between displayed result and the canonical publication source monitored by defenders. Direct page or wallpaper overwrite defines the parent but is not automatically stealthy. If the adversary preserves the canonical source while replacing the identifier-to-source binding, origin integrity can remain normal while the audience receives an attacker page. Site access, a web shell, or invisible script without a display outcome is adjacent behavior.")),
 "stealth_characteristics":PP(("篡改最终通常要被目标受众看到，匿迹价值在影响前后防守观察错位。源绑定被替换后，恶意内容、访问和证书痕迹位于替代服务器或解析路径，规范文件、CMS 和部署历史没有对应变化；只检查源站或单一探测点的守方可能把报告误判为缓存或客户端故障。","Defacement is usually intended to be visible to its audience; stealth value lies in defender-observation mismatch before and around impact. After source binding changes, malicious content, access, and certificate traces reside at the substitute server or resolution path, while canonical files, CMS, and deployment history have no corresponding change. Origin-only or single-vantage defenders may misclassify reports as cache or client faults."),("残余包括注册或托管区变更、前后 RRset、TTL、跨解析器答案、DNSSEC、替代 IP/证书、HTTP 重定向和正文/视觉哈希，以及规范源与用户内容差分。独立观察点、长期控制面日志与发布快照可恢复链条；合法故障切换、CDN 迁移、维护页、A/B 测试和区域化是反例。","Residue includes registrar or hosted-zone changes, before and after RRsets, TTLs, cross-resolver answers, DNSSEC, substitute IP and certificate, HTTP redirects and body or visual hashes, and a differential between canonical source and user content. Independent vantages, long-lived control-plane logs, and publication snapshots restore the chain. Legitimate failover, CDN migration, maintenance pages, A/B tests, and localization are counterexamples.")),
 "scope_boundary_definition":PP(("纳入组织控制或被冒用的展示身份/界面实际向人呈现未经授权内容的行为，需要确认展示身份、可见结果和攻击行为到结果的关系。CMS 首页即使存于数据库中，只要直接对象是展示页面仍属本技术。","Include behavior that actually presents unauthorized content to a person under an organization-controlled or appropriated display identity or interface. Classification requires the display identity, visible result, and adversary-to-result relation. A CMS home page remains in scope even when stored in a database if the direct object is the displayed page."),("T1565 负责业务数据值、传输数据或运行时数据变化以影响流程、理解或决策；业务记录在界面显示不自动成为 T1491。相似域克隆站和凭据页归钓鱼，承载命令或载荷的网页归 C2/投放，未改变人类可见内容的 Web shell 和普通站点攻陷不纳入。DNS 改道只有在组织身份下出现恶意展示时才确认本技术。","T1565 owns business-value, transmitted-data, or runtime-data changes affecting process, understanding, or decision; rendering a manipulated record does not automatically make it T1491. Lookalike cloned sites and credential pages belong to phishing, web content carrying commands or payloads to C2 or staging, and web shells or compromise without changed human-facing content are excluded. DNS diversion confirms this technique only when malicious display appears under the organization identity.")),
 "application_scenarios_and_threat_model":context(P("攻击者接管注册商或权威 DNS 账户，把组织网站的 A、AAAA、CNAME 或 NS 绑定改到托管篡改页面的服务器，同时保留真实源站。内部场景还包括入口、登录 banner 或桌面消息，但直接本地修改保持父级核心；伴随加密、擦除和凭据盗取分别建模。","An attacker can take over a registrar or authoritative-DNS account and point an organization's A, AAAA, CNAME, or NS binding to a server hosting a defacement page while preserving the real origin. Internal scenarios include portals, login banners, or desktop messages, while direct local changes remain parent core; accompanying encryption, wiping, and credential theft are modeled separately."),P("攻击者需修改内容源或标识到源绑定的权限、选择高价值表面的知识和足够驻留时间。绑定替换需要控制注册、权威 DNS、解析或等效映射并提供替代内容；HTTPS 还可能需要可接受证书。注册锁、MFA、双人批准、DNSSEC、带外通知、缓存与快速回滚限制效果。","The attacker needs authority over content source or identifier-to-source binding, knowledge of a high-value surface, and enough residence time. Binding substitution requires control of registration, authoritative DNS, resolution, or equivalent mapping and a substitute source; HTTPS may require an accepted certificate. Registry locks, MFA, dual approval, DNSSEC, out-of-band notification, caching, and rapid rollback constrain it."),P("防守方分别取得内容库/CMS 版本、FIM、部署审计、注册/DNS 变更、递归答案、TLS 证书、多地域 HTTP/视觉快照和用户报告，并连接批准发布到实际输出以及名称绑定到内容源。只有源站 FIM、一个解析器或缺少前态 RRset 时，展示与原因会拆散。","Defenders separately obtain content-repository or CMS versions, FIM, deployment audit, registration and DNS changes, recursive answers, TLS certificates, multiregion HTTP or visual snapshots, and user reports and join approved publication to output and name binding to source. Origin FIM alone, one resolver, or missing prior RRsets separates display from cause.")),
 "stealth_mechanisms":[mechanism("NM-BT","primary",B("解析绑定替换使恶意展示落在规范源监测之外","Resolution-binding replacement moves malicious display outside canonical-source monitoring"),P("攻击者不修改受监测源站，而把组织展示标识指向攻击者服务器。关键变化落在注册或解析控制面，用户请求在另一源结束；源站 FIM、CMS 审计和部署哈希保持正常。防守若未连接 DNS 变化、跨解析器答案和实际 HTTP 内容就看不到原因。","The attacker leaves the monitored origin unchanged and directs the organization display identifier to an attacker server. The critical change resides in registration or resolution control, and user requests terminate at another source; origin FIM, CMS audit, and deployment hashes stay normal. Without joining DNS changes, cross-resolver answers, and actual HTTP content, defenders miss the cause."),["REF-000884","REF-000885","REF-000887","REF-000888"],"high")],
 "subtechnique_taxonomy":{"narrative":PP(("当前只保留展示源绑定替换：组织标识与规范内容源的绑定被替换，而规范源自身不变；痕迹从文件/CMS 平面转到注册、解析或发布控制面。内部/外部、网站/桌面、文件/数据库和平台都不是边界。","The taxonomy retains only Display-Source Binding Substitution: the binding between organization identifier and canonical content source is replaced while the canonical source remains unchanged, moving traces from the file or CMS plane to registration, resolution, or publication control. Internal/external, website/desktop, file/database, and platform do not define boundaries."),("T1491.001 和 .002 仅表示展示位置，不能形成原生匿迹兄弟项。按受众条件呈现、低差分覆盖和集中委托发布缺少结论级 T1491 证据，暂不进入正式分类。","T1491.001 and .002 describe display location only and cannot form native stealth siblings. Audience-conditioned presentation, low-difference overlays, and centralized delegated publication lack conclusion-level T1491 evidence and remain outside the formal taxonomy.")),"coverage":"established","subtechnique_refs":["NJS-0187-001"]},
 "defense":defense(["DET-000215"],["MIT-000196"]),"evidence":{"claim_refs":["CLM-000917","CLM-000918","CLM-000919","CLM-000920"],"case_refs":["CASE-000269"],"reference_refs":["REF-000882","REF-000883","REF-000884","REF-000885","REF-000886","REF-000887","REF-000888","REF-000889","REF-000890","REF-000029","REF-000524"]},
 "research":{"limitations":PP(("ATT&CK 锚定父行为，ICANN Hushmail 调查直接证明 DNS 绑定替换与篡改结果；该单一 2005 外部域名事件不能证明 CDN、内部 DNS、MDM/GPO 或条件呈现具有相同链。DNS 变化本身也不证明篡改，必须保留实际内容与规范源状态。","ATT&CK anchors the parent and ICANN's Hushmail investigation directly establishes DNS binding substitution and a defacement outcome. One 2005 external-domain case cannot establish identical chains for CDN, internal DNS, MDM/GPO, or conditioned presentation. DNS change alone does not prove defacement; actual content and canonical-source state are required."),("动态页面、合法区域化、缓存传播、TLS 错误和缺失控制面日志限制检测。多观察点数量和五分钟轮次是调优起点而非来源测得阈值。","Dynamic pages, legitimate localization, cache propagation, TLS errors, and absent control-plane logs limit detection. Vantage count and five-minute polling are tuning starts rather than source-measured thresholds."))},"lifecycle":life()})

write(f"{T1491_DIR}/subtechniques/NJS-0187-001-display-source-binding-substitution/subtechnique.yaml", {
 "schema_version":"2.0.0","type":"evasion-subtechnique","id":"NJS-0187-001","parent_ref":"NJT-0187","name":B("展示源绑定替换","Display-Source Binding Substitution"),"summary":B("攻击者保留组织展示标识和规范源，却把标识绑定到替代内容源，使源站监控看似正常而用户看到篡改页面。","An adversary preserves the organization display identifier and canonical source but binds the identifier to a substitute source, leaving origin monitoring normal while users see a defaced page."),"aliases":[],"lineage":{"attck_subtechnique_inherited":False},
 "definition_and_concept":PP(("展示源绑定替换是攻击者不修改规范发布源，而改变组织展示标识到实际内容源的注册、DNS、路由或等效发布映射，使受众在组织身份下取得攻击者内容。稳定变量是标识—源关系被替换且规范源保持批准状态，不是 DNS 产品或内外位置。","Display-Source Binding Substitution changes registration, DNS, routing, or an equivalent publication mapping from an organization display identifier to the actual source without modifying the canonical publication source, causing audiences to receive attacker content under the organization identity. The stable variable is a replaced identifier-to-source relation with an approved canonical source, not DNS product or internal/external location."),("完成要求异常绑定或答案实际把用户引向替代源、替代源呈现未经授权内容且规范源仍是批准版本。只有注册变更、DNS 错误、证书异常或路径风险不确认展示篡改。","Completion requires an anomalous binding or answer actually directing users to a substitute source, unauthorized content at that source, and a canonical origin still at the approved version. Registration change, DNS error, certificate anomaly, or path risk alone does not confirm defacement.")),
 "stealth_characteristics":PP(("展示源绑定替换让源站文件、CMS 版本和部署审计保持干净，恶意内容和访问痕迹落在替代服务器与解析路径。只检查规范源的防守方得到正常完整性结果，用户却看到篡改页面，造成跨观察面的行为透明。","Display-Source Binding Substitution leaves origin files, CMS versions, and deployment audit clean while malicious content and access traces reside at a substitute server and resolution path. Origin-only defenders receive a normal integrity result while users see a defaced page, producing behavioral transparency across observation planes."),("注册/DNS 主体、前后 RRset、TTL、DNSSEC、跨解析器答案、替代证书、HTTP 正文和视觉哈希仍可恢复链。若已有带外域名通知、多观察点抓取和规范源比较，优势会缩小。","Registrar and DNS actor, before and after RRsets, TTL, DNSSEC, cross-resolver answers, substitute certificate, HTTP body, and visual hash remain available to restore the chain. Out-of-band domain notifications, multivantage retrieval, and canonical-source comparison reduce the advantage.")),
 "scope_boundary_definition":PP(("纳入组织标识仍被受众使用、绑定被未经授权替换、实际页面或界面被篡改且规范源未发生对应批准变化的情况。正常 CDN/GeoDNS、故障转移、迁移、维护页和缓存传播是反例。","Include cases where audiences still use the organization identifier, its binding is replaced without authorization, an actual page or interface is defaced, and the canonical source has no matching approved change. Normal CDN or GeoDNS, failover, migration, maintenance pages, and cache propagation are counterexamples."),("DNS 改道只窃取凭据、读取流量或造成不可用时分别评估钓鱼、中间路径或拒绝服务。直接修改源站内容保持父级核心；内部或外部位置不改变子项边界。","DNS diversion used only to steal credentials, read traffic, or cause outage is assessed as phishing, intermediary path, or denial of service. Direct origin modification remains parent core, and internal or external location does not alter the child boundary.")),
 "application_scenarios_and_threat_model":context(P("攻击者接管注册商或权威 DNS，将高价值网站名称指向托管篡改页的服务器，在真实源站和 CMS 不变时向公众展示恶意消息。Hushmail 事件证明注册控制、DNS 改向、替代页面和干净源站的完整链。","An attacker takes over a registrar or authoritative DNS and points a high-value website name to a server hosting a defaced page, presenting an attacker message while the real origin and CMS remain unchanged. Hushmail establishes the full chain from registration control and DNS diversion to substitute page and clean origin."),P("攻击者需要注册、权威 DNS 或客户端接受的解析路径权限，知道目标名称与记录并控制替代内容源。HTTPS 还需可接受证书或可容忍错误；TTL、DNSSEC、注册锁、通知和快速回滚限制覆盖与驻留。","The attacker needs authority over registration, authoritative DNS, or a client-accepted resolution path, knowledge of the target name and records, and a substitute content source. HTTPS also requires an acceptable certificate or tolerance for errors; TTL, DNSSEC, registry locks, notification, and rollback constrain coverage and residence."),P("防守方独立保存注册/DNS 变更身份、前后 RRset 与审批，从权威与多个递归器记录答案，并用相同 Host/SNI 抓取 TLS/HTTP 内容与规范源比较。单一解析器可能只见缓存，源站监控只证明源站未改，公共探测可能错过内部/选择性答案。","Defenders independently retain registration and DNS actor, before and after RRsets, and approval, record answers from authoritative and multiple recursive resolvers, and retrieve TLS/HTTP content with the same Host and SNI for canonical comparison. One resolver may see only cache state, origin monitoring proves only the origin is unchanged, and public probes may miss internal or selective answers.")),
 "stealth_mechanisms":[mechanism("NM-BT","primary",B("源绑定替换绕开规范源完整性观察","Source-binding substitution bypasses canonical-source integrity observation"),P("攻击者把组织标识映射到替代服务器，关键变化进入注册/解析控制面，用户内容不再来自被 FIM 和发布审计覆盖的规范源。源站检查因此正常而影响已发生；跨 DNS 变化、解析答案、证书和实际内容关联能恢复原因。","The attacker maps an organization identifier to a substitute server, moving the critical change into registration or resolution control while user content no longer comes from the canonical source covered by FIM and publication audit. Origin checks remain normal while impact occurs; joining DNS change, answers, certificate, and actual content restores the cause."),["REF-000884","REF-000887","REF-000888"],"high")],
 "defense":defense(["DET-000215"],["MIT-000196"]),"evidence":{"claim_refs":["CLM-000919","CLM-000920"],"case_refs":["CASE-000269"],"reference_refs":["REF-000884","REF-000885","REF-000887","REF-000888","REF-000889","REF-000890","REF-000524"]},
 "research":{"limitations":PP(("正式结论主要依赖 Hushmail 外部域名案例和规范文档，不能证明所有 DNS 劫持都以匿迹为目的，亦不能直接推广到现代 CDN、内部解析或选择性回答。","The formal conclusion relies mainly on the external-domain Hushmail case and normative documentation. It does not prove every DNS hijack has a stealth purpose or directly generalize to modern CDN, internal resolution, or selective answers."),("没有实际页面快照、用户观察或等价输出证据时，只能确认路径风险；缓存、证书错误和短驻留也可能使部分受众从未看到篡改内容。","Without an actual page snapshot, user observation, or equivalent output evidence, only path risk is established. Cache, certificate errors, and brief residence can also mean some audiences never saw defacement."))},"lifecycle":life()})

T1495_DIR="matrix/tactics/TA0040-impact/techniques/NJT-0188-observation-collapsing-firmware-corruption"
write(f"{T1495_DIR}/technique.yaml", {
 "schema_version":"2.0.0","type":"technique","id":"NJT-0188","name":B("观察链坍塌型固件破坏","Observation-Collapsing Firmware Corruption"),"summary":B("攻击者破坏启动或组件初始化所依赖的非易失固件，使设备不可用，并同时切断设备自身对破坏后状态的观察与报告。","Adversaries corrupt nonvolatile firmware required for boot or component initialization, making the device unavailable while severing its own observation and reporting of the post-corruption state."),"aliases":["Firmware Corruption","T1495"],
 "classification":{"tactic_refs":["TA0040"],"origin":{"kind":"attack-adapted","source_attack_id":"T1495","source_attack_version":"19.1"},"decision_ref":"DEC-TA0040-T1495"},
 "definition_and_concept":PP(("观察链坍塌型固件破坏是攻击者未授权覆写、擦除或损坏平台或组件非易失存储中的固件代码及启动关键数据，使硬件无法初始化、操作系统无法接管，或组件不能提供预期功能。直接对象是硬件在上电或初始化阶段消费的固件状态与可用性结果，不是更新工具、品牌或普通磁盘内容。","Observation-Collapsing Firmware Corruption is unauthorized adversary overwrite, erase, or damage to firmware code or boot-critical data in platform or component nonvolatile storage so hardware cannot initialize, the operating system cannot take control, or a component cannot provide expected function. The direct object is firmware state consumed by hardware at power-on or initialization and the resulting availability loss, not update tool, brand, or ordinary disk content."),("Niji 的附加条件是破坏同时移除同一设备的有效观察面：主机日志、EDR、管理代理或常规固件读回无法在变化后启动或响应，守方只能从变化前远程日志、外部控制器、证明失败或离线硬件取证重建原因。停机明显，匿迹效果位于受损设备无法自证写入者、固件差和根因。","Niji adds the condition that corruption also removes an effective observation plane on the same device. Host logs, EDR, management agents, or ordinary firmware readback cannot start or respond after the change, forcing reconstruction from pre-change remote logs, external controllers, attestation failure, or offline forensics. The outage is conspicuous; the stealth effect lies in the damaged device's inability to establish writer, firmware difference, and root cause itself.")),
 "stealth_characteristics":PP(("变化可由高权进程、驱动、闪存工具或暂存更新发起；一旦损坏内容在重启或组件初始化被消费，系统可在 OS、日志转发和传感器启动前停止。守方看到电源存在但 POST/启动/心跳缺失、组件消失或更新失败，而不是本机连续记录的攻击者写入—固件差—不可用链。","A privileged process, driver, flash utility, or staged update can initiate the change. Once corrupted content is consumed during reboot or initialization, the platform can stop before the OS, log forwarder, and sensor start. Defenders see power without POST, boot, or heartbeat, a missing component, or update failure rather than a locally continuous chain from attacker write to firmware difference to unavailability."),("残余包括刷写进程、驱动签名/hash、固件资源 GUID 与状态、审批、重启、TPM PCR/TCG 日志、BMC/串口 POST、心跳断点、已知良好映像和离线读回。不同权证明和不可变日志缩小盲区；设备自报版本与本地 agent 在成功破坏后失去独立性。","Residue includes flashing process, driver signature and hash, firmware-resource GUID and status, approval, reboot, TPM PCR and TCG log, BMC or serial POST, heartbeat break, known-good image, and offline readback. Differently authorized attestation and immutable logs reduce the blind spot; device self-reported version and local agent lose independence after successful corruption.")),
 "scope_boundary_definition":PP(("纳入要求攻击者控制的未授权固件变化、目标确为硬件消费的非易失对象、变化被上电/重启/初始化实际消费，以及设备或组件不可用且同一设备正常观察或读回失效。只有刷写工具、可写 SPI、hash 异常、暂存包或一次启动失败最多证明 exposure/anomaly。","Include only with an adversary-controlled unauthorized firmware change, a true hardware-consumed nonvolatile target, actual consumption at power-on, reboot, or initialization, and resulting device or component unavailability together with loss of the same device's ordinary observation or readback. A flashing tool, writable SPI, hash anomaly, staged package, or one boot failure establishes exposure or anomaly at most."),("能启动并在 OS 前运行恶意代码归 NJT-0097；网络设备运行修改映像并继续服务归 NJT-0167；完成受限启动且防御缺席归 NJT-0172；磁盘扇区、MBR、分区和文件系统擦除归 T1561。合法签名更新因电源/兼容/硬件故障失败并回滚、厂商诊断与自然故障是反例。","Malicious code that boots before the OS belongs to NJT-0097; a network device running a modified image while continuing service to NJT-0167; completed restricted boot with missing defenses to NJT-0172; and disk-sector, MBR, partition, and filesystem wiping to T1561. A legitimate signed update failing from power, compatibility, or hardware error and rolling back, vendor diagnostics, and natural failure are counterexamples.")),
 "application_scenarios_and_threat_model":context(P("攻击者取得内核或硬件接口访问后，可加载具有 SPI/物理内存写能力的驱动，识别芯片组和 BIOS 写保护，再擦除或覆写启动固件；也可滥用更新权限暂存重启时消费的破坏映像。CIH 证明 Flash BIOS 随机覆写能阻止重启，TrickBoot 只证明现代写入前提和可行性。","After obtaining kernel or hardware-interface access, an adversary can load a driver with SPI or physical-memory write capability, identify chipset and BIOS protection, and erase or overwrite boot firmware, or abuse update authority to stage a destructive image consumed at reboot. CIH establishes that random Flash BIOS overwrite can prevent reboot; TrickBoot establishes only modern prerequisites and feasibility."),P("攻击者需要固件更新、SPI/flash、BMC 或等价低层写权限，准确识别型号、区域和写保护，并在验证/回滚前提交变化。硬件写保护、签名 capsule、最低版本、独立恢复根和错误写入过早 brick 会限制行动。","The attacker needs firmware-update, SPI or flash, BMC, or equivalent low-level write authority, accurate model, region, and write-protection knowledge, and commitment before validation or rollback. Hardware write protection, signed capsules, minimum versions, independent recovery roots, and premature bricking constrain the operation."),P("防守方在破坏前观察主体、包来源/hash/签名、进程/驱动、重启和固件资源状态；启动边界取得 TPM/TCG，失联后依靠不同权 BMC、串口、电源、集中日志、已知良好映像与离线读回。无硬件信任根、组件未测量或 BMC 同时失陷时，恶意破坏与合法故障仍是竞争解释。","Before corruption, defenders observe actor, package source/hash/signature, process and driver, reboot, and firmware-resource status; at boot they obtain TPM or TCG evidence, and after loss rely on differently authorized BMC, serial, power, centralized logs, known-good images, and offline readback. Without a hardware root, with an unmeasured component, or with a compromised BMC, malicious corruption and benign failure remain competing explanations.")),
 "stealth_mechanisms":[mechanism("NM-DO","primary",B("破坏固件同时终止设备自身的启动后观察与读回","Firmware corruption also terminates the device's own post-boot observation and readback"),P("攻击者损坏硬件启动或初始化必须消费的固件；生效后 OS、agent 与常规读回不能启动，原应由本机记录的固件变化和后继状态从观察链消失，只剩变化前写入痕迹、外部失联和硬件证据。匿迹效果是内容/根因从同一设备观察面脱落，而不是停机本身不被看见。","The adversary corrupts firmware required by hardware boot or initialization. After consumption, the OS, agent, and ordinary readback cannot start, removing the firmware difference and successor state from the local observation chain and leaving pre-change write traces, external loss, and hardware evidence. The stealth effect is the content and root cause dropping from the same-device observation plane, not invisibility of the outage itself."),["REF-000892","REF-000194","REF-000897"],"medium")],
 "subtechnique_taxonomy":{"narrative":PP(("开放搜索只确认在带观察坍塌这一稳定变量，它定义适配父级且作为唯一子项会同义重复。直接 flash 与 capsule、即时与重启消费、平台/外设类别及完全/部分损坏分别是路径、时机、目标或严重度。","Open search confirms only in-band observation collapse as a stable variable, defining the adapted parent and becoming redundant as a sole child. Direct flash versus capsule, immediate versus reboot consumption, platform versus peripheral, and complete versus partial damage are path, timing, target, or severity distinctions."),("破坏恢复固件属于 T1490 边界，触发门控由执行 taxonomy 负责；现有来源不足以建立另一个有独立防御的 NJS，因此覆盖为 none-justified。","Corrupting recovery firmware meets the T1490 boundary, and trigger gating belongs to execution taxonomy. Current sources do not establish another NJS with independent defense, so coverage is none-justified.")),"coverage":"none-justified","subtechnique_refs":[]},
 "defense":defense(["DET-000216"],["MIT-000077"]),"evidence":{"claim_refs":["CLM-000921","CLM-000922","CLM-000923","CLM-000924"],"case_refs":[],"reference_refs":["REF-000891","REF-000892","REF-000194","REF-000893","REF-000894","REF-000895","REF-000896","REF-000897","REF-000366","REF-000898"]},
 "research":{"limitations":PP(("CIH 来源证明破坏能力与 no-boot 症状，NIST 证明固件韧性和独立恢复需求；来源没有命名受害者事件完整写入链，也未声明攻击者为隐匿根因而选择固件破坏。因此父行为高置信，观察坍塌机理中等且无 CASE。","The CIH source establishes destructive capability and no-boot symptoms, while NIST supports firmware resiliency and independent recovery. Sources do not provide a named victim with a complete write chain or state that the attacker chose corruption to conceal root cause. Parent behavior is high confidence, the observation-collapse mechanism medium, and no CASE is created."),("很多旧设备缺少远程证明、BMC 或可读固件，恢复本身会改变证据。没有外部可信源、实际消费和离线差分时，只能报告固件完整性/启动异常，不能断言恶意破坏。","Many legacy devices lack remote attestation, BMC, or readable firmware, and recovery can alter evidence. Without an external trust source, actual consumption, and offline differential, report firmware integrity or boot anomaly rather than malicious corruption."))},"lifecycle":life()})

T1496_DIR="matrix/tactics/TA0040-impact/techniques/NJT-0189-resource-hijacking"
write(f"{T1496_DIR}/technique.yaml", {
 "schema_version":"2.0.0","type":"technique","id":"NJT-0189","name":B("资源劫持","Resource Hijacking"),"summary":B("攻击者未经授权消耗受害方资源完成自身任务，并通过活动门控或提供方计量执行使消耗更像正常容量波动或合法交易。","Adversaries consume victim resources for their own tasks and use activity gating or provider-metered execution to make usage resemble normal capacity variation or legitimate transactions."),"aliases":["T1496"],
 "classification":{"tactic_refs":["TA0040"],"origin":{"kind":"attack-adapted","source_attack_id":"T1496","source_attack_version":"19.1"},"decision_ref":"DEC-TA0040-T1496"},
 "definition_and_concept":PP(("资源劫持是攻击者未经资源所有者授权，使用受控主机、容器、云账户、网络出口、消息平台或托管服务执行攻击者任务，消耗计算周期、带宽、消息额度、模型令牌、配额或费用预算。直接对象是可计量资源及 owner，影响为费用、配额、性能、容量或受害身份承担的外部滥用。","Resource Hijacking is adversary use of a controlled host, container, cloud account, network egress, messaging platform, or managed service without owner authorization to perform an adversary task, consuming compute cycles, bandwidth, messages, model tokens, quota, or spending budget. The direct object is a metered resource and its owner, with cost, quota, performance, capacity, or external abuse attributed to the victim."),("概念锚连接主体/入口、实际消费动作、资源计量、批准 owner/用途和结果。挖矿、代理、短信、AI 和垃圾消息是用途，同一资源可有多种用途；只有有证据改变消费时间包络或执行观察面的方式进入原生子项。","The concept joins principal or entry, actual consumption, resource meter, approved owner and purpose, and outcome. Mining, proxying, SMS, AI, and spam are uses and one resource can have many uses; only evidenced changes to the consumption envelope or execution observation plane enter native children.")),
 "stealth_characteristics":PP(("持续满载或突发滥用易产生性能和账单峰值。攻击者可读取用户空闲或竞争负载，只在剩余容量出现时运行消费者，降低忙时异常；也可让云/通信提供方在受害账户下执行计量事务，使主机 EDR 没有对应工作进程，生产侧只出现看似有效请求。","Continuous saturation or burst abuse creates performance and billing spikes. An attacker can read user idle or competing load and run a consumer only when residual capacity appears, reducing busy-period anomalies, or have a cloud or communications provider execute metered transactions under the victim account, leaving host EDR without a corresponding worker and production with apparently valid requests."),("进程 lineage、CPU/GPU/网络计量、会话状态、服务主体、请求 ID、号码、模型、令牌、配额和费用仍可观察。owner 基线、活动状态关联、按主体计量和服务事务日志缩小优势；后台批处理、扩缩容、OTP 峰值和模型测试是反例。","Process lineage, CPU/GPU/network meters, session state, service principal, request ID, number, model, tokens, quota, and cost remain observable. Owner baselines, activity-state correlation, per-principal metering, and service transaction logs reduce the advantage; background batches, autoscaling, OTP peaks, and model tests are counterexamples.")),
 "scope_boundary_definition":PP(("纳入攻击者实际使用受害资源完成自身任务，并能证明用量、费用、配额或容量影响及相应匿迹变量。只创建实例、取得 shell、探测 API、安装代理或保存凭据是前置；费用异常也需排除批准扩容、增长、价格变化和配置错误。","Include actual adversary use of victim resources for an adversary task with proven usage, cost, quota, or capacity effect and its stealth variable. Instance creation, shell access, API probes, proxy installation, or stored credentials are precursors. Cost anomalies also require exclusion of approved scaling, growth, price changes, and configuration mistakes."),("工作负载执行、凭据、C2 与持久化保留各自对象；低覆盖区域归 NJT-0121，竞争驻留驱逐归 NJT-0091，直接以耗尽为目标归 DoS，资金转移归 T1657。资源种类、厂商、矿池、号码国家与收益方式不形成 NJS。","Workload execution, credentials, C2, and persistence retain their own objects. Low-coverage Region placement belongs to NJT-0121, competing-foothold eviction to NJT-0091, direct exhaustion objectives to DoS, and fund transfer to T1657. Resource type, vendor, pool, destination country, and revenue form do not define NJS.")),
 "application_scenarios_and_threat_model":context(P("交互端点上的矿工可按空闲输入、游戏或流媒体负载暂停/恢复，在用户不易感知时消耗剩余 GPU/CPU。云环境可在容器/VM 运行矿工或代理。托管服务中，窃取凭据可调用模型推理，公开 OTP 表单可驱动提供方向攻击者号码发送短信，受害方承担令牌、消息与费用。","A miner on an interactive endpoint can pause and resume according to idle input, gaming, or streaming load, consuming residual GPU or CPU when less noticeable. Cloud environments can run miners or proxies in containers or VMs. In managed services, stolen credentials can invoke models and a public OTP form can drive a provider to send SMS to attacker numbers, leaving tokens, messages, and cost to the victim."),P("攻击者需要执行消费者或调用计量服务的权限、收益/任务返回路径和足够驻留/凭据寿命。活动门控需读取用户/负载并暂停消费者；提供方消费需有效 API/表单入口、额度和服务。限额、短期身份、owner 绑定、事务限制和隔离降低收益。","The attacker needs authority to execute a consumer or invoke a metered service, a return path for profit or task, and sufficient foothold or credential life. Activity gating needs user or load visibility and pausing; provider consumption needs a valid API or form entry, quota, and service. Limits, short-lived identity, owner binding, transaction controls, and isolation reduce yield."),P("防守方观察进程、性能计数、网络、用户活动、云身份/API、提供方调用、令牌/消息、费用和配额，把计量映射到 owner、批准工作负载和来源，并跨分钟活动切换与日/周费用保持多尺度关联。高 CPU 阈值漏看活动门控，主机 EDR 漏看提供方执行，月账单发现过晚。","Defenders observe processes, performance counters, network, user activity, cloud identity and API, provider invocation, tokens or messages, cost, and quota; map meters to owner, approved workload, and origin; and correlate minute-level activity changes with daily or weekly spending. High-CPU thresholds miss gating, host EDR misses provider execution, and monthly billing detects too late.")),
 "stealth_mechanisms":[mechanism("NM-ST","primary",B("消费移动到空闲窗口并在竞争活动出现时收缩","Consumption shifts into idle windows and contracts when competing activity appears"),P("攻击者持续读取用户空闲或 GPU/业务负载，在竞争活动出现时终止消费者、空闲恢复后重启。资源痕迹从持续高负载变为与用户活动负相关的时间片段，局部阈值和体验难以重建累计消耗；长期活动—资源相关仍揭示闭环。","The adversary continuously reads idle or GPU/business load and stops the consumer when competing activity appears, restarting after idle. Resource traces change from sustained load to time fragments negatively correlated with user activity, weakening local thresholds and user experience as measures of total consumption; long-horizon activity-resource correlation reveals the loop."),["REF-000900","REF-000906","REF-000907"],"high"),mechanism("NM-BT","secondary",B("提供方执行把消耗移出受害主机传感器","Provider execution moves consumption outside victim host sensors"),P("攻击者提交看似有效的模型、消息或验证请求，提供方执行并把实际工作计入受害账户；主机进程与本地资源视图没有对应工作，守方必须转向身份、服务调用和计量日志。事务 ID、主体、目标、令牌/消息和费用仍可关联。","The attacker submits apparently valid model, messaging, or verification requests while the provider executes and meters work to the victim account. Host processes and local-resource views have no corresponding work, requiring identity, service-call, and meter logs. Transaction ID, principal, target, tokens or messages, and cost remain correlatable."),["REF-000901","REF-000902","REF-000903","REF-000904"],"medium")],
 "subtechnique_taxonomy":{"narrative":PP(("活动门控的剩余容量消耗按闭环活动信号控制何时消费划分；提供方代理的计量资源消耗按实际执行/计量位于外部提供方而主机无对应消费者划分。两者可共现，但时间包络和观察域不互相蕴含，防御数据不同。","Activity-Gated Residual-Capacity Consumption is defined by a closed-loop activity signal controlling when consumption runs. Provider-Brokered Metered Consumption is defined by execution and metering at an external provider without a corresponding host consumer. They can co-occur, but time envelope and observation domain do not imply each other and require different defense data."),("T1496.001–.004 按资源与变现形式划分且不导入。计算为活动门控提供证据，短信与托管服务为提供方计量提供证据，带宽保持父级。跨资产稀释与 victim-IP 归因转移证据不足，区域选择和竞争者驱逐由既有技术负责。","T1496.001–.004 partition resource and monetization forms and are not imported. Compute supplies activity-gating evidence, SMS and hosted services supply provider-metering evidence, and bandwidth remains parent core. Cross-asset dilution and victim-IP attribution transfer lack evidence, while Region selection and competitor eviction have existing owners.")),"coverage":"established","subtechnique_refs":["NJS-0189-001","NJS-0189-002"]},
 "defense":defense(["DET-000217","DET-000218"],["MIT-000197","MIT-000198"]),"evidence":{"claim_refs":["CLM-000925","CLM-000926","CLM-000927","CLM-000928","CLM-000929","CLM-000930"],"case_refs":["CASE-000270"],"reference_refs":["REF-000899","REF-000900","REF-000901","REF-000902","REF-000903","REF-000904","REF-000905","REF-000906","REF-000907","REF-000908","REF-000909","REF-000910","REF-000598","REF-000604","REF-000524"]},
 "research":{"limitations":PP(("Microsoft 案例高质量支持 Windows 交互端 GPU 活动门控，扩展到 CPU、带宽或服务器负载需降低置信度。Sysdig 观察凭据探测、配置查询与模型调用尝试，但潜在日费用不是实际损失；Twilio 提供字段和模式而非受害案例。","Microsoft's case strongly supports activity-gated GPU use on interactive Windows endpoints; extension to CPU, bandwidth, or server load needs lower confidence. Sysdig observed credential probes, configuration inquiry, and attempted model calls, while potential daily cost is not realized loss; Twilio supplies fields and patterns rather than a victim case."),("账单、配额和性能异常可由正常增长产生，必须恢复 owner、批准用途与实际交易。提供方子项为中等置信且无 CASE；平台字段不可互换。","Billing, quota, and performance anomalies can arise from normal growth and require owner, approved purpose, and actual transactions. The provider child is medium confidence without a CASE; platform fields are not interchangeable."))},"lifecycle":life()})

write(f"{T1496_DIR}/subtechniques/NJS-0189-001-activity-gated-residual-capacity-consumption/subtechnique.yaml", {
 "schema_version":"2.0.0","type":"evasion-subtechnique","id":"NJS-0189-001","parent_ref":"NJT-0189","name":B("活动门控的剩余容量消耗","Activity-Gated Residual-Capacity Consumption"),"summary":B("攻击者根据用户空闲或竞争负载暂停和恢复消费者，只在剩余容量窗口运行恶意任务。","An adversary pauses and resumes a consumer according to user idle state or competing load, running malicious work only in residual-capacity windows."),"aliases":[],"lineage":{"attck_subtechnique_inherited":False},
 "definition_and_concept":PP(("活动门控的剩余容量消耗是攻击者持续取得用户输入、会话、GPU/CPU 或业务负载反馈，并用该反馈决定恶意消费者何时启动、暂停或终止，使任务主要占用暂时未被合法活动使用的容量。稳定变量是反馈闭环控制的时间包络，不是低固定速率、夜间计划或矿工产品。","Activity-Gated Residual-Capacity Consumption continually obtains user-input, session, GPU/CPU, or business-load feedback and uses it to decide when a malicious consumer starts, pauses, or stops, concentrating the task in capacity temporarily unused by legitimate activity. The stable variable is the feedback-controlled time envelope, not a fixed low rate, nighttime schedule, or miner product."),("消费仍必须完成攻击者任务并产生可计量用量；仅查询空闲状态或部署调度代码是前置。活动出现时可靠收缩、空闲恢复时重启以及资源结果共同形成该子项。","Consumption must still perform an adversary task and create metered usage; querying idle state or deploying scheduler code is a precursor. Reliable contraction when activity appears, restart when idle returns, and resource outcome together form the child.")),
 "stealth_characteristics":PP(("活动门控的剩余容量消耗把持续高负载变为与用户活动负相关的分散片段，降低用户可感卡顿与短窗口阈值。合法活动越强，恶意消费者越弱或消失，使常规忙时抽样看到正常资源竞争；跨空闲—活动转换的长期分析却会看到同一进程反复随反馈启停。","Activity-Gated Residual-Capacity Consumption converts sustained high load into dispersed fragments negatively correlated with user activity, reducing user-visible slowdown and short-window thresholds. As legitimate activity increases, the malicious consumer weakens or disappears, leaving normal competition in busy-period samples. Long-horizon analysis across idle-to-active transitions reveals one process repeatedly starting and stopping with feedback."),("残余包括反馈 API/会话事件、矿工进程 lineage、资源计数、暂停/退出、重启任务和矿池/收益网络。固定低资源合法任务是反例，只有反馈关系与未经授权 owner 差共同成立才确认。","Residue includes feedback APIs or session events, miner-process lineage, resource counters, pause or exit, restart task, and pool or profit network. Legitimate fixed-low-resource jobs are counterexamples; feedback relation and unauthorized owner differential must both hold.")),
 "scope_boundary_definition":PP(("纳入未经授权消费者的资源使用与用户/工作负载状态之间有重复、因果一致的负相关，并能连接到实际任务输出。单纯夜间运行、固定 CPU 上限、一次暂停或正常节能不满足。","Include repeated, causally consistent negative correlation between unauthorized consumer resource use and user or workload state joined to actual task output. Nighttime operation, a fixed CPU cap, one pause, or normal power saving alone do not qualify."),("消费者启动归执行，重启计划归持久化，进程隐藏归相应 stealth owner，竞争矿工清除归 NJT-0091；本项只描述反馈如何改变资源消费时间。","Consumer start belongs to execution, restart scheduling to persistence, process hiding to its stealth owner, and competing-miner removal to NJT-0091. This child describes only how feedback changes the timing of resource consumption.")),
 "application_scenarios_and_threat_model":context(P("攻击者在 Windows 交互端部署 GPU 矿工，轮询最后输入与 GPU 负载；游戏、流媒体或用户活动出现时关闭矿工，空闲若干时间后由编排器重启。相同原理只有在证据证明闭环时才能扩展到 CPU 或业务服务器。","An attacker deploys a GPU miner on an interactive Windows endpoint and polls last input and GPU load, terminating it when gaming, streaming, or user activity appears and restarting through an orchestrator after idle returns. The principle extends to CPU or servers only with evidence of a closed loop."),P("攻击者需执行消费者和反馈监测、可靠暂停/重启、保持收益通道并承受较低产量。应用控制、受保护任务/服务、资源隔离、会话审计和矿池限制提高成本。","The attacker needs consumer and feedback-monitor execution, reliable pause and restart, a profit channel, and tolerance for lower yield. Application control, protected tasks or services, resource isolation, session audit, and pool restrictions raise cost."),P("防守方关联进程唯一键、CPU/GPU 计数、锁定/解锁或输入空闲、进程停止/重启和网络目的，比较批准后台任务。短窗口高负载规则会漏检；性能计数无进程维度或活动事件缺失时只能报告 ownerless intermittent load。","Defenders join process unique keys, CPU/GPU counters, lock/unlock or input idle, process stop/restart, and network destination against approved background jobs. Short-window high-load rules miss it; counters without process dimension or absent activity events yield only ownerless intermittent load.")),
 "stealth_mechanisms":[mechanism("NM-ST","primary",B("反馈闭环把消费分散到用户空闲与剩余容量窗口","A feedback loop disperses consumption into user-idle and residual-capacity windows"),P("攻击者监视活动反馈并在合法竞争出现时收缩消费者，空闲时恢复。持续用量变成跨窗口碎片，短阈值和用户感知低估累计消耗，形成时空释痕；把活动转换与同一消费者资源变化长期关联可恢复闭环。","The attacker monitors activity feedback and contracts the consumer when legitimate competition appears, restoring it during idle. Continuous usage becomes cross-window fragments, causing short thresholds and user experience to underestimate cumulative consumption and producing spatiotemporal trace dilution. Long-horizon joining of activity transitions to the same consumer's resource changes restores the loop."),["REF-000900","REF-000905","REF-000906","REF-000907"],"high")],
 "defense":defense(["DET-000217"],["MIT-000197"]),"evidence":{"claim_refs":["CLM-000926","CLM-000928","CLM-000930"],"case_refs":["CASE-000270"],"reference_refs":["REF-000900","REF-000905","REF-000906","REF-000907","REF-000598","REF-000604"]},
 "research":{"limitations":PP(("在野证据直接支持 Windows 交互端 GPU 矿工读取活动反馈并启停；不能无条件推广到 CPU、带宽和服务器。具体 idle 秒数是样本实现而非子项边界或阈值。","Field evidence directly supports a GPU miner on interactive Windows endpoints reading activity feedback and stopping or restarting. It cannot be generalized unconditionally to CPU, bandwidth, and servers. Exact idle seconds are a sample implementation, not the child boundary or threshold."),("合法维护、渲染和批处理也可在空闲运行，进程 owner、批准用途、收益网络和重复闭环必须共同验证。","Legitimate maintenance, rendering, and batch jobs can also run when idle; process owner, approved purpose, profit network, and repeated loop must be verified together."))},"lifecycle":life()})

write(f"{T1496_DIR}/subtechniques/NJS-0189-002-provider-brokered-metered-consumption/subtechnique.yaml", {
 "schema_version":"2.0.0","type":"evasion-subtechnique","id":"NJS-0189-002","parent_ref":"NJT-0189","name":B("提供方代理的计量资源消耗","Provider-Brokered Metered Consumption"),"summary":B("攻击者提交有效 API 或表单请求，让外部提供方执行并向受害账户计量任务，使主机端没有对应消费者。","An adversary submits valid API or form requests so an external provider executes and meters work to the victim account without a corresponding host consumer."),"aliases":[],"lineage":{"attck_subtechnique_inherited":False},
 "definition_and_concept":PP(("提供方代理的计量资源消耗是攻击者利用有效云身份、API key 或公共应用入口，提交会触发模型推理、消息发送或其他计费任务的请求，由服务提供方完成实际工作并记入受害账户。稳定变量是执行和计量位于提供方数据面，而受害主机没有对应消费者进程；服务类型不是边界。","Provider-Brokered Metered Consumption uses a valid cloud identity, API key, or public application entry to submit requests that trigger model inference, message delivery, or another billable task performed and charged by the provider. The stable variable is execution and metering in the provider data plane without a corresponding victim-host consumer process; service type does not define the boundary."),("完成要求成功服务事务和受害账户资源/费用/配额结果。凭据探测、ValidationException、未发送的 OTP 请求或潜在费用估算只表示前置风险；必须与真实调用或提供方发送记录相连。","Completion requires a successful service transaction and resource, cost, or quota outcome on the victim account. Credential probes, ValidationException, an OTP request with no send, or potential-cost estimates establish precursor risk only and must join an actual invocation or provider delivery record.")),
 "stealth_characteristics":PP(("提供方代理的计量资源消耗使主机 EDR 与本地性能计数没有模型计算或消息发送进程，生产侧可能只看到经认证 API 或普通验证码请求。实际执行、目标和计量位于提供方日志，若这些日志默认未启用、分区域或只在账单后出现，业务侧检测难以及时理解资源消耗。","Provider-Brokered Metered Consumption leaves host EDR and local counters without a model-compute or message-send process, while production may see only authenticated API or ordinary verification requests. Execution, target, and metering reside in provider logs. If those logs are disabled by default, regional, or visible only through later billing, business-side detection struggles to understand consumption promptly."),("服务主体、来源、user-agent、请求/交易 ID、模型、token、号码、转换状态、配额和费用仍可连接。按应用 owner、主体、目标及转换率计量能缩小盲区；合法新应用、负载测试、OTP 峰值与跨区故障转移是反例。","Service principal, origin, user-agent, request or transaction ID, model, tokens, number, conversion state, quota, and cost remain joinable. Metering by application owner, principal, target, and conversion rate reduces the blind spot. Legitimate new applications, load tests, OTP peaks, and cross-Region failover are counterexamples.")),
 "scope_boundary_definition":PP(("纳入提供方成功执行并计量的未经授权事务，且组织无法把主体、用途、来源或目标与批准应用对应。只有 API 登录、服务枚举、日志配置查询、表单请求或费用告警不够；需实际服务结果。","Include successful provider-executed and metered unauthorized transactions where the organization cannot map principal, purpose, origin, or target to an approved application. API login, service enumeration, logging-configuration inquiry, form request, or cost alert alone is insufficient; an actual service result is required."),("在受害 VM/容器内运行矿工或代理属于父级/其他子项，不因云托管而进入本项。低覆盖区域选择归 NJT-0121；短信、AI、SaaS 和提供方名称是实现，不能再拆 NJS。","A miner or proxy running inside a victim VM or container remains parent or another child and does not enter merely because it is cloud hosted. Low-coverage Region choice belongs to NJT-0121. SMS, AI, SaaS, and provider names are implementations and do not create more NJS.")),
 "application_scenarios_and_threat_model":context(P("攻击者用窃取云凭据调用托管模型，或自动化公开 OTP/验证入口让消息提供方向攻击者号码发送高成本短信。服务执行计算或投递并记入受害账户，端点无对应进程。","An attacker uses stolen cloud credentials to invoke a hosted model or automates a public OTP or verification entry so a messaging provider sends costly messages to attacker numbers. The service executes compute or delivery and meters the victim account without an endpoint process."),P("攻击者需要有效身份或可驱动提供方事务的公共入口、足够配额和把输出/收益接回自身的目标。短期分应用身份、服务禁用、事务速率/目的地控制、模型/消息限额和 bot 挑战会降低收益。","The attacker needs a valid identity or public entry that drives provider transactions, sufficient quota, and a target returning output or profit. Short-lived per-app identity, disabled services, transaction rate or destination controls, model or message limits, and bot challenges reduce yield."),P("防守方启用每个允许区域的提供方调用/交易日志，连接 CloudTrail 或应用入口、主体、来源、请求 ID、模型/token 或号码/转换，并映射 owner、预算和批准用途。共享角色、无请求映射、日志延迟或被盗批准应用会削弱判断。","Defenders enable provider invocation or transaction logs in each allowed Region and join CloudTrail or application entry, principal, origin, request ID, model and token or number and conversion to owner, budget, and approved purpose. Shared roles, absent request mapping, log delay, or a compromised approved app weaken judgment.")),
 "stealth_mechanisms":[mechanism("NM-BT","primary",B("提供方执行把消费移出受害主机资源观察面","Provider execution moves consumption outside victim-host resource observation"),P("攻击者提交有效请求，提供方完成实际计算或发送并向受害账户计量；主机没有消费者进程或本地资源峰值，只看端点的守方无法看到任务。转向服务事务、身份和用量日志可恢复行为链。","The attacker submits a valid request, and the provider performs the compute or delivery and meters the victim account. The host has no consumer process or local-resource spike, so endpoint-only defenders cannot see the task. Provider transaction, identity, and usage logs restore the chain."),["REF-000901","REF-000902","REF-000903","REF-000904","REF-000524"],"medium")],
 "defense":defense(["DET-000218"],["MIT-000198"]),"evidence":{"claim_refs":["CLM-000927","CLM-000929","CLM-000930"],"case_refs":[],"reference_refs":["REF-000901","REF-000902","REF-000903","REF-000904","REF-000908","REF-000909","REF-000524"]},
 "research":{"limitations":PP(("Sysdig 直接观察凭据与服务探测、反向代理线索及模型调用尝试，但验证阶段没有运行合法模型查询，潜在每日费用不是实际损失。Twilio 提供交易字段和 pumping 模式而非命名案例，因此子项为中等置信且无 CASE。","Sysdig directly observed credential and service probes, reverse-proxy evidence, and attempted model calls, but the validation phase did not run legitimate model queries and potential daily cost is not realized loss. Twilio provides transaction fields and pumping patterns rather than a named case, so the child is medium confidence without a CASE."),("提供方字段、日志默认值和计费语义不可互换。没有成功事务和 owner 差时，只能报告服务滥用风险；账单异常可能晚于实际影响。","Provider fields, log defaults, and billing semantics are not interchangeable. Without a successful transaction and owner differential, only service-abuse risk can be reported; billing anomaly may lag impact."))},"lifecycle":life()})


def req(source_type, name, channel, fields):
    return {"source_type":source_type,"name":name,"channel":channel,"required_fields":fields}
def strategy(n, slug, name, summary, description, targets, analytic_ids, refs):
    write(f"detections/DET-{n:06d}-{slug}.yaml", {"schema_version":"2.0.0","type":"detection-strategy","id":f"DET-{n:06d}","name":name,"summary":summary,"description":description,"detects_refs":targets,"domains":["enterprise"],"analytic_refs":analytic_ids,"evidence_refs":refs,"lifecycle":life()})
def analytic(n, slug, det, name, summary, platforms, logic, requirements, observables, window, dimensions, fps, blind, tuning, refs):
    write(f"analytics/NJA-{n:06d}-{slug}.yaml", {"schema_version":"2.0.0","type":"detection-analytic","id":f"NJA-{n:06d}","strategy_ref":det,"name":name,"summary":summary,"domains":["enterprise"],"platforms":platforms,"logic":logic,"data_requirements":requirements,"observables":observables,"correlation":{"window":window,"dimensions":dimensions},"false_positives":fps,"blind_spots":blind,"tuning_guidance":tuning,"evidence_refs":refs,"lifecycle":life()})

strategy(213,"business-service-stop-lineage",B("业务服务控制到可用性结果谱系","Business-Service Control to Availability-Outcome Lineage"),B("连接服务停止调用者、状态转换、审批与独立业务健康，识别看似维护的恶意中断。","Join service-stop caller, state transition, approval, and independent business health to identify malicious interruption resembling maintenance."),PP(("本策略面向业务服务停止，不因一个 stopped 状态单独告警。Analytic 恢复命令或 API 调用进程、主体与会话、SERVICE_STOP 权限、服务状态序列和业务健康结果，并与变更单及服务 owner 比较。防御工具和恢复服务按各自 owner 处理。","This strategy covers business-service stopping without alerting on a stopped state alone. The analytic recovers command or API caller process, principal and session, SERVICE_STOP authority, service-state sequence, and business-health outcome and compares change ticket and service owner. Defensive and recovery services retain their own owners.")),["NJT-0185"],["NJA-000261"],["REF-000865","REF-000866","REF-000867","REF-000868","REF-000598","REF-000869","REF-000871"])
analytic(261,"windows-business-service-stop-outcome","DET-000213",B("Windows 业务服务停止调用与结果分析","Windows Business-Service Stop Caller and Outcome Analytic"),B("输出未经批准的服务控制者、有序停止状态和实际业务不可用链。","Emit a chain of unapproved service controller, orderly stopped state, and actual business unavailability."),["Windows"],PP(("采集 DeviceProcessEvents/4688 中 net.exe、sc.exe、PowerShell、WMI 和其他调用者，规范化服务控制命令并按设备、主体、登录会话、进程唯一键和服务名关联。直接 API 路径没有包装器时，使用服务句柄访问或 EDR API 行为；调用后两分钟内验证运行→停止待定→停止或启动类型变化。","Collect net.exe, sc.exe, PowerShell, WMI, and other callers from DeviceProcessEvents or 4688, normalize service-control actions, and correlate by device, principal, logon session, process unique key, and service name. For direct APIs without wrappers, use service-handle access or EDR API behavior. Verify running to stop-pending to stopped or start-type change within two minutes."),("在五分钟内连接服务依赖和外部健康失败，在三十分钟内连接维护审批、远程来源及后继加密/删除，但后继只提升事件链置信度。目标必须在业务服务清单中；安全与恢复职责转交相邻 owner。","Within five minutes join dependencies and external health failure, and within thirty minutes join maintenance approval, remote origin, and successor encryption or deletion, with successors raising chain confidence only. The target must be in the business-service inventory; security and recovery roles route to adjacent owners.")),[req("endpoint-process-event",B("端点进程与命令事件","Endpoint process and command events"),"DeviceProcessEvents or Security 4688",["event.timestamp","device.id","process.unique.id","process.name","process.command.line","account.sid","logon.id","parent.process.unique.id"]),req("service-state-event",B("服务控制与状态事件","Service control and state events"),None,["event.timestamp","device.id","service.name","service.role","controller.process.id","requested.control","state.before","state.after","start.type"]),req("business-health-probe",B("独立业务健康与审批","Independent business health and approval"),None,["event.timestamp","service.name","health.result","business.owner","approval.id","maintenance.window"])],[B("未经批准主体请求标准停止并出现停止终态","An unapproved principal requests a standard stop and the service reaches stopped"),B("服务停止与独立业务健康失败及后继数据活动相连","Service stop joins an independent health failure and successor data activity")],B("停止状态序列两分钟，业务结果五分钟，审批与攻击链三十分钟；按服务启动耗时调优。","Use two minutes for state sequence, five for business outcome, and thirty for approval and attack-chain context; tune by service startup and shutdown behavior."),["device.id","service.name","account.sid","logon.id","process.unique.id","event.timestamp"],[B("批准补丁、升级、故障转移、容量维护、管理员排障和依赖服务编排","Approved patching, upgrades, failover, capacity maintenance, administrator troubleshooting, and dependency orchestration")],[B("直接 API 无句柄遥测、远程管理来源丢失、agent 与服务一起失效或业务健康探针缺失","Direct APIs without handle telemetry, lost remote-management origin, agent failure with the service, or absent business-health probe")],P("按服务角色、owner、常见控制程序和维护窗口建基线，但不对 SYSTEM 或管理员永久放行。严重度需要未经批准控制与独立业务结果组合；命令命中但状态未变只报企图。","Baseline by service role, owner, common controller, and maintenance window without permanently allowing SYSTEM or administrators. Severity requires unapproved control plus independent business outcome; command hits without state change remain attempts."),["REF-000866","REF-000867","REF-000868","REF-000598","REF-000869","REF-000871"])

strategy(214,"recovery-state-transition-outcome",B("恢复状态转换与结果关联","Recovery-State Transition and Outcome Correlation"),B("连接恢复控制动作、恢复对象/策略结果和受保护资源覆盖，识别直接与延迟恢复抑制。","Join recovery-control action, recovery object or policy outcome, and protected-resource coverage to identify direct and deferred recovery inhibition."),PP(("该策略以恢复职责为确认门槛，使用 Windows 状态差和 AWS Backup 生命周期两套 Analytic。命令/API/策略变化先产生企图或事前风险，只有恢复副本、配置、RPO 或恢复测试结果下降才确认；生产当前数据状态不替代恢复结果。","This strategy uses recovery role as the confirmation gate and separate Windows state-differential and AWS Backup lifecycle analytics. Commands, APIs, or policy changes first create an attempt or pre-impact risk; only reduced copies, configuration, RPO, or restore-test outcome confirms. Current production-data state does not replace a recovery outcome.")),["NJT-0186","NJS-0186-001"],["NJA-000262","NJA-000263"],["REF-000869","REF-000598","REF-000872","REF-000873","REF-000874","REF-000875","REF-000876","REF-000877","REF-000524"])
analytic(262,"windows-recovery-control-state","DET-000214",B("Windows 恢复控制命令与状态差分","Windows Recovery-Control Command and State Differential"),B("连接恢复控制进程链和卷影、WinRE、目录前后状态，区分企图与确认损失。","Join recovery-control process lineage to before-and-after shadow, WinRE, and catalog state to separate attempt from confirmed loss."),["Windows"],PP(("从 DeviceProcessEvents 选择 vssadmin、wbadmin、diskshadow、bcdedit、reagentc、wmic、PowerShell 或 shell 的删除卷影、目录、禁用恢复或 WMI 删除参数，按 DeviceId 与进程唯一键在十分钟内连接父子链。保留完整参数、账户、路径、hash 和 ReportId。","Select vssadmin, wbadmin, diskshadow, bcdedit, reagentc, wmic, PowerShell, or shell activity with shadow/catalog deletion, recovery-disable, or WMI-delete arguments from DeviceProcessEvents and join process lineage by DeviceId and unique keys over ten minutes. Preserve full arguments, account, path, hash, and ReportId."),("三十分钟内比较独立恢复清单前后态：shadow ID/数量、WinRE、备份目录/版本和批准单。成功状态下降确认父级；命令失败或状态不变是企图。可在后六小时连接加密/销毁以显示攻击链，但不能反推恢复损失。","Within thirty minutes compare an independent recovery inventory before and after: shadow IDs and count, WinRE, backup catalog and versions, and approval. Successful state reduction confirms the parent; failed commands or unchanged state are attempts. Encryption or destruction in the next six hours can show an attack chain but cannot infer recovery loss.")),[req("defender-process-event",B("Defender 设备进程事件","Defender device process events"),"DeviceProcessEvents",["timestamp","device.id","process.unique.id","process.name","process.command.line","account.sid","initiating.process.unique.id","file.sha1","folder.path","report.id"]),req("recovery-state-inventory",B("组织恢复状态清单","Organization recovery-state inventory"),None,["asset.id","collection.time","shadow.copy.id","winre.status","backup.catalog.id","backup.version.id","state.hash","approval.id"])],[B("原生命令或 API 后恢复对象数量、WinRE 或目录状态下降","Recovery-object count, WinRE, or catalog state declines after a native command or API"),B("恢复抑制后六小时内出现加密或销毁链","Encryption or destruction appears within six hours after recovery inhibition")],B("进程链十分钟，动作到状态三十分钟，后继链六小时。","Use ten minutes for process lineage, thirty for action-to-state, and six hours for successor-chain context."),["device.id","process.unique.id","account.sid","recovery.object.id","collection.time"],[B("灾备演练、OS 修复、快照轮换、备份迁移、容量维护和厂商清理","DR exercises, OS repair, snapshot rotation, backup migration, capacity maintenance, and vendor cleanup")],[B("直接 COM/API、未管理主机、无前态清单、远程存储删除或存在但无法恢复的副本","Direct COM or API, unmanaged hosts, absent prior inventory, remote storage deletion, or a copy that exists but cannot restore")],P("按关键资产维护管理主体与工单，但不全局放行 SYSTEM、备份账户或原生工具。区分企图、状态损失和恢复失败；高价值资产使用更严格审批而非更高数量阈值。","Maintain administrative-principal and ticket baselines by critical asset without globally allowing SYSTEM, backup accounts, or native tools. Separate attempt, state loss, and restore failure; use stricter approval rather than a higher count for high-value assets."),["REF-000869","REF-000598","REF-000872","REF-000873"])
analytic(263,"aws-backup-policy-expiry-lineage","DET-000214",B("AWS Backup 策略、恢复点与服务到期谱系","AWS Backup Policy, Recovery Point, and Service-Expiry Lineage"),B("输出未经批准的恢复点直接删除或策略驱动到期及其受保护资源 RPO 结果。","Emit unapproved direct recovery-point deletion or policy-driven expiry with protected-resource RPO outcome."),["IaaS"],PP(("在 CloudTrail 识别 DeleteRecoveryPoint、UpdateRecoveryPointLifecycle、UpdateBackupPlan、DeleteBackupPlan/Selection 和 DeleteBackupVaultLockConfiguration。直接删除对成功请求立即告警，并按主体/vault 在十五分钟聚合恢复点。策略变化保存前后 DeleteAfterDays 与 CalculatedLifecycle DeleteAt，比较最低保留与审批。","Identify DeleteRecoveryPoint, UpdateRecoveryPointLifecycle, UpdateBackupPlan, DeleteBackupPlan or Selection, and DeleteBackupVaultLockConfiguration in CloudTrail. Alert immediately on successful direct deletion and aggregate points by principal and vault over fifteen minutes. Preserve before and after DeleteAfterDays and CalculatedLifecycle DeleteAt for policy changes and compare retention floors and approval."),("把策略事件保留到 DeleteAt 加服务删除上限，连接 BackupDeleted、恢复点清单和 resourceArn，计算幸存恢复点是否满足 RPO。策略变化为事前风险；实际删除或 RPO 缺口确认结果。锁拒绝保持企图。","Retain the policy join through DeleteAt plus the service deletion bound and connect BackupDeleted, recovery inventory, and resourceArn to calculate whether surviving points meet RPO. Policy change is pre-impact risk; actual deletion or RPO gap confirms outcome. A lock-denied request remains an attempt.")),[req("aws-backup-cloudtrail",B("AWS Backup CloudTrail 事件","AWS Backup CloudTrail events"),"CloudTrail",["event.time","event.name","aws.region","account.id","user.identity.arn","source.ip","user.agent","backup.vault.name","recovery.point.arn","resource.arn","event.id","error.code"]),req("backup-policy-version",B("备份策略与恢复点状态","Backup policy and recovery-point state"),None,["backup.vault.name","recovery.point.arn","resource.arn","policy.version","delete.after.days","calculated.delete.at","vault.lock.mode","approval.id"]),req("recovery-coverage",B("恢复覆盖与 RPO 清单","Recovery coverage and RPO inventory"),None,["resource.arn","criticality","rpo.required","recovery.point.count","latest.point.time","restore.test.result"])],[B("未经批准的恢复点删除或保留期限缩短","Unapproved recovery-point deletion or retention shortening"),B("服务到期导致关键资源的幸存恢复点低于 RPO","Service expiry leaves a critical resource below RPO")],B("直接删除十五分钟；生命周期变化从写入持续到 Calculated DeleteAt 加八小时；按产品时限调优。","Use fifteen minutes for direct deletes; retain lifecycle joins from write to Calculated DeleteAt plus eight hours, tuned to product timing."),["account.id","aws.region","backup.vault.name","recovery.point.arn","resource.arn","user.identity.arn","policy.version","calculated.delete.at"],[B("批准保留调整、资源退役、测试 vault 清理、迁移和正常到期","Approved retention changes, resource retirement, test-vault cleanup, migration, and normal expiry")],[B("源服务外删除、组织 trail 缺失、跨账户副本漏清单、服务事件缺少原主体或恢复依赖不可见","Deletion outside Backup, missing organization trail, omitted cross-account copies, service events without original principal, or invisible restore dependencies")],P("按工作负载层级维护最低保留、批准 policy hash 与锁模式，区分失败与成功调用，不对 root/备份管理员全局放行。RPO 确认需要完整恢复点清单，真正可恢复性仍需演练。","Maintain retention floors, approved policy hashes, and lock modes by workload tier; separate failed and successful calls and never globally allow root or backup administrators. RPO confirmation needs complete inventory, while actual recoverability still requires exercises."),["REF-000874","REF-000875","REF-000876","REF-000877","REF-000524"])

strategy(215,"publication-display-integrity-lineage",B("批准发布状态至实际展示谱系","Approved Publication State to Observed Display Lineage"),B("比较批准发布、名称绑定和实际展示，确认未经授权可见变化并定位内容源或解析控制面。","Compare approved publication, name binding, and actual display to confirm unauthorized visible change and locate the content-source or resolution control plane."),PP(("策略使用发布输出差分与绑定到输出谱系两个 Analytic。第一个确认实际人类可见结果与批准 release 不一致，并定位规范源是否修改；第二个在规范源干净时连接注册/DNS 变化、跨解析器答案、TLS/HTTP 内容与替代页面。站点攻陷或 DNS 变化没有可见结果时不确认。","The strategy uses publication-output differential and binding-to-output lineage analytics. The first confirms human-visible output differs from the approved release and locates whether the canonical source changed. The second joins registrar or DNS change, cross-resolver answers, TLS/HTTP content, and substitute page when the origin remains clean. Site compromise or DNS change without visible result is not confirmed.")),["NJT-0187","NJS-0187-001"],["NJA-000264","NJA-000265"],["REF-000882","REF-000884","REF-000885","REF-000887","REF-000888","REF-000889","REF-000890","REF-000524"])
analytic(264,"approved-publication-output-differential","DET-000215",B("批准发布状态—实际展示差分","Approved Publication State–Observed Display Differential"),B("输出批准 release 与实际人类可见页面、banner 或界面之间的未经授权语义和视觉差。","Emit unauthorized semantic and visual differences between an approved release and the human-visible page, banner, or interface."),[],PP(("为高价值展示面登记 surface、owner、规范源、批准 release 和允许的地域/语言/认证变体。事件触发并至少每五分钟用匹配画像取得实际结果，规范化时间戳、nonce 和批准个性化槽后比较语义文本、DOM/UI 与视觉 hash。","Register surface, owner, canonical source, approved release, and allowed regional, language, or authenticated variants for each high-value display. Retrieve actual output on events and at least every five minutes with a matching profile, normalize timestamps, nonces, and approved personalization slots, and compare semantic text, DOM or UI, and visual hashes."),("未经批准可见差分在前后 24 小时连接文件、CMS、对象、壁纸/banner 和部署控制面变化，输出 source-modified、rendered-only-divergence 或 authorized-variant。源保持批准而输出变化时转交绑定 Analytic。","Join an unauthorized visible difference to file, CMS, object, wallpaper or banner, and deployment changes over the surrounding 24 hours and emit source-modified, rendered-only-divergence, or authorized-variant. If the source remains approved while output changes, route to the binding analytic.")),[req("display-surface-inventory",B("展示面与批准发布清单","Display surface and approved-release inventory"),None,["surface.id","surface.type","owner.id","canonical.source.id","approved.release.id","variant.profile","criticality"]),req("publication-change-audit",B("内容发布变更审计","Publication change audit"),None,["event.time","surface.id","source.id","actor.id","operation","object.id","hash.before","hash.after","release.id","approval.id"]),req("display-output-observation",B("实际展示输出观察","Observed display output"),None,["event.time","surface.id","viewer.profile","vantage.id","result.status","content.hash","semantic.hash","visual.hash","evidence.id"])],[B("未经批准的语义或视觉输出与当前 release 不一致","Unauthorized semantic or visual output differs from the current release"),B("源站批准状态正常而用户观察持续偏离","The origin remains approved while user-visible output persistently diverges")],B("同轮观察五分钟；发布变更与展示结果前后 24 小时，按发布周期调优。","Use five minutes for one observation round and 24 hours around publication change and output, tuned to publication cadence."),["surface.id","viewer.profile","vantage.id","source.id","release.id","actor.id","event.time"],[B("批准发布/回滚、维护页、A/B 测试、区域化、CDN 缓存和用户壁纸","Approved release or rollback, maintenance pages, A/B testing, localization, CDN cache, and user wallpaper")],[B("交互后出现内容、未覆盖认证页面、动态页面无法规范化、无历史 release 或攻击者同步篡改审批","Content appearing after interaction, uncovered authenticated pages, non-normalizable dynamic pages, absent release history, or co-tampered approval")],P("为每个 surface 登记允许变体和过期时间，按 DOM 区域、语义和视觉组合比较；批准发布身份不得永久白名单。高风险表面保留不依赖生产 CDN/解析的观察点。","Register allowed variants and expiry per surface and combine DOM-region, semantic, and visual comparison; never permanently allow an approved publisher identity. Keep a high-risk vantage independent of production CDN and resolution."),["REF-000882","REF-000884","REF-000885"])
analytic(265,"name-binding-content-source-display","DET-000215",B("名称绑定—内容源—展示结果谱系","Name Binding–Content Source–Display Outcome Lineage"),B("确认异常 DNS/注册绑定把组织名称引向未经授权页面，而规范源保持批准内容。","Confirm an anomalous DNS or registration binding directs an organization name to unauthorized content while the canonical source remains approved."),[],PP(("在 DNS/注册变更触发时和固定五分钟轮次，从权威与至少多个独立递归/地域观察点解析高价值名称，保存 NS、CNAME、A/AAAA 链、TTL、DNSSEC 与答案来源。对每个答案用相同 Host/SNI 抓取证书、重定向、正文/语义/视觉 hash，并与规范源比较。","On DNS or registration change and fixed five-minute rounds, resolve high-value names from authoritative and multiple independent recursive or regional vantages, preserving NS, CNAME, A or AAAA chain, TTL, DNSSEC, and answer source. Retrieve certificate, redirects, body, semantic, and visual hashes for each answer with the same Host and SNI and compare the canonical source."),("把控制面 actor、前后记录、change ID 和审批连接到答案传播与页面差。异常绑定/答案、未经授权可见内容和干净规范源共同成立才输出 display-source-substitution-confirmed；只有 IP、证书或 DNS 错误保留为路径异常。","Join control-plane actor, before and after records, change ID, and approval to answer propagation and page difference. Emit display-source-substitution-confirmed only when anomalous binding or answer, unauthorized visible content, and a clean canonical source all hold; IP, certificate, or DNS error alone remains a path anomaly.")),[req("dns-registration-control",B("注册与 DNS 控制面","Registration and DNS control plane"),"Registrar audit and Route 53 CloudTrail",["event.time","actor.id","event.name","domain.id","record.name","record.type","action","rdata.old","rdata.new","ttl","change.id","approval.id"]),req("multivantage-dns-answer",B("多观察点 DNS 答案","Multivantage DNS answers"),"Authoritative and recursive probes",["event.time","vantage.id","resolver.id","qname","qtype","rcode","answers","ttl","dnssec.status","authoritative.ns"]),req("tls-http-display",B("TLS/HTTP 展示内容观察","TLS and HTTP display observation"),None,["event.time","vantage.id","qname","resolved.ip","sni","certificate.fingerprint","http.status","redirect.chain","content.hash","semantic.hash","visual.hash"])],[B("未经批准 RRset 或注册变化与替代页面同时出现","An unapproved RRset or registration change co-occurs with a substitute page"),B("同一组织名称跨解析器返回超出批准流量工程的内容源差","The organization name returns source differences beyond approved traffic engineering across resolvers")],B("同轮五分钟；控制面变化连接到 max(2×旧 TTL, 1 小时)，上限 24 小时。","Use five minutes for one round; join control change through max of twice the old TTL or one hour, capped at 24 hours."),["domain.id","record.name","record.type","change.id","resolver.id","vantage.id","resolved.ip","certificate.fingerprint","event.time"],[B("批准 DNS/CDN 迁移、灾备故障切换、蓝绿发布、GeoDNS/Anycast、DDoS sinkhole 和过期缓存","Approved DNS or CDN migration, DR failover, blue-green release, GeoDNS or Anycast, DDoS sinkhole, and stale cache")],[B("未抽样递归器、DoH/DoT 绕过、注册商无审计、同步篡改审批、复用批准 CDN/证书或短于探测间隔的改向","Unsampled resolver, DoH or DoT bypass, absent registrar audit, co-tampered approval, reuse of approved CDN or certificate, or diversion shorter than polling")],P("登记批准 NS/RRset、ASN/CDN、证书、内容变体和变更窗口；不按 IP 变化单独告警。用户报告触发临时高频抓取，每个例外记录 owner、approval 和到期。","Register approved NS or RRsets, ASN or CDN, certificates, content variants, and change windows; do not alert on IP change alone. User reports trigger temporary high-frequency retrieval and each exception carries owner, approval, and expiry."),["REF-000884","REF-000887","REF-000888","REF-000889","REF-000890","REF-000524"])

strategy(216,"firmware-write-boot-failure-lineage",B("固件写入—启动失败—外部证据谱系","Firmware Write–Boot Failure–External Evidence Lineage"),B("连接固件写入前痕迹、重启消费、证明/POST/心跳失败和离线读回，区分恶意破坏与更新故障。","Join pre-corruption firmware-write traces, reboot consumption, attestation or POST or heartbeat failure, and offline readback to distinguish malicious corruption from update failure."),PP(("策略确认固件对象、攻击者控制的写入、实际消费和 no-boot/组件不可用结果，并要求一个不同权观察面。Analytic 把进程/驱动和 ESRT 状态连接到重启后的证明、BMC/串口与心跳，再以恢复读回验证。只有可写性、包暂存或一次启动失败不确认。","The strategy confirms a firmware object, attacker-controlled write, actual consumption, and no-boot or component-unavailability outcome and requires a differently authorized observation plane. The analytic joins process, driver, and ESRT state to post-reboot attestation, BMC or serial, and heartbeat and verifies with recovery readback. Writeability, staged package, or one boot failure alone does not confirm.")),["NJT-0188"],["NJA-000266"],["REF-000891","REF-000892","REF-000194","REF-000893","REF-000894","REF-000895","REF-000896","REF-000897","REF-000366"])
analytic(266,"windows-firmware-corruption-outcome","DET-000216",B("Windows 固件写入与启动观察坍塌分析","Windows Firmware Write and Boot Observation-Collapse Analytic"),B("输出异常刷写/驱动、固件状态变化、重启后失联和可信恢复差分的闭合链。","Emit a closed chain of anomalous flash or driver, firmware state change, post-reboot loss, and trusted recovery differential."),["Windows"],PP(("在重启前十五分钟连接异常刷写工具/驱动加载、签名/hash、低层访问、固件资源 GUID、LastAttemptVersion/Status、更新包与审批。被拒绝或成功回滚的尝试保持 exposure。","Within fifteen minutes before reboot, join anomalous flashing utility or driver load, signature and hash, low-level access, firmware-resource GUID, LastAttemptVersion and Status, update package, and approval. Rejected or successfully rolled-back attempts remain exposure."),("跨至少两次启动尝试或 24 小时连接 boot ID、TPM PCR/TCG、BMC/串口 POST、外部电源/网络、集中 heartbeat 和预期 OS agent。确认需要未授权写入后持续 no-boot/组件缺失，且可信恢复或离线读回显示固件差。","Across at least two boot attempts or 24 hours, join boot ID, TPM PCR or TCG, BMC or serial POST, external power or network, centralized heartbeat, and expected OS agent. Confirmation requires persistent no-boot or missing component after an unauthorized write and a firmware difference from trusted recovery or offline readback.")),[req("endpoint-process-driver",B("端点刷写进程与驱动","Endpoint flashing process and driver"),"DeviceProcessEvents and Sysmon Event 6",["event.time","device.id","process.unique.id","process.name","process.command.line","driver.path","driver.hash","driver.signature","account.sid"]),req("firmware-resource-status",B("固件资源与更新状态","Firmware resource and update status"),"ESRT and FirmwareResources inventory",["device.id","firmware.guid","version.current","last.attempt.version","last.attempt.status","package.hash","approval.id","reboot.time"]),req("external-boot-evidence",B("外部启动与证明证据","External boot and attestation evidence"),None,["device.id","boot.id","pcr.value","tcg.log.hash","bmc.post.code","serial.result","heartbeat.time","power.state","network.state"]),req("firmware-recovery-readback",B("可信恢复与固件读回","Trusted recovery and firmware readback"),None,["device.id","hardware.model","known.good.hash","readback.hash","recovery.method","recovery.result"])],[B("异常硬件写入驱动或固件包之后设备在 OS 前持续失联","The device persistently disappears before the OS after an anomalous hardware-write driver or firmware package"),B("外部证明或离线读回显示固件与已知良好映像不同","External attestation or offline readback differs from the known-good firmware")],B("写入到重启十五分钟；至少两次启动或 24 小时确认持续失败，并保留恢复证据。","Use fifteen minutes from write to reboot and at least two boots or 24 hours to confirm persistence, preserving recovery evidence."),["device.id","process.unique.id","driver.hash","firmware.guid","boot.id","event.time"],[B("批准固件升级失败、电源中断、硬件故障、兼容性问题、厂商恢复和计划主板更换","Approved firmware update failure, power loss, hardware fault, incompatibility, vendor recovery, and planned motherboard replacement")],[B("无硬件证明或 BMC、组件未测量、固件无法读回、设备完全断电或 BMC 同时受控","No hardware attestation or BMC, unmeasured component, unreadable firmware, complete power loss, or compromised BMC")],P("按 hardware GUID/型号维护批准包、签名、版本和维护窗口。单次更新失败保持低置信；只有 writer/包、消费、外部持续失败和可信差分闭合才升级。先保全证据再恢复。","Maintain approved packages, signatures, versions, and maintenance windows by hardware GUID or model. Keep one update failure low confidence; escalate only when writer or package, consumption, external persistent failure, and trusted differential close. Preserve evidence before recovery."),["REF-000893","REF-000894","REF-000895","REF-000896","REF-000897","REF-000366","REF-000194"])

strategy(217,"activity-gated-resource-consumption",B("活动状态—资源消费者负相关","Activity-State to Resource-Consumer Negative Correlation"),B("识别消费者随用户或业务活动上升而暂停、空闲后恢复的闭环资源使用。","Identify a resource consumer that pauses as user or business activity rises and resumes after idle in a closed loop."),PP(("策略覆盖资源劫持父级端点路径与活动门控子项。Analytic 不依赖一次高 CPU 峰值，而连接进程 lineage、GPU/CPU 计数、会话/输入活动、进程启停和网络输出；实际资源 owner 与批准任务决定是否未授权。提供方服务消费由另一策略处理。","This strategy covers the endpoint path of Resource Hijacking and the activity-gated child. The analytic does not rely on one high-CPU spike and joins process lineage, GPU or CPU counters, session or input activity, process stop and start, and network output. Resource owner and approved job determine authorization. A separate strategy covers provider consumption.")),["NJT-0189","NJS-0189-001"],["NJA-000267"],["REF-000900","REF-000905","REF-000906","REF-000907","REF-000598","REF-000604"])
analytic(267,"interactive-resource-activity-loop","DET-000217",B("交互活动与资源消费者闭环分析","Interactive Activity and Resource-Consumer Loop Analytic"),B("输出同一未经授权进程在空闲期消费、活动期退出并反复恢复的负相关模式。","Emit a repeated negative-correlation pattern where the same unauthorized process consumes during idle, exits during activity, and resumes."),["Windows"],PP(("从 DeviceProcessEvents 形成消费者与编排器进程 lineage，加入 DeviceNetworkEvents 的目的地和字节及 Perf 的进程/实例 CPU 或 GPU 计数。采集会话锁定/解锁、登录 ID 和可信输入空闲值；以进程唯一键而非名称追踪。","Build consumer and orchestrator process lineage from DeviceProcessEvents, add destination and bytes from DeviceNetworkEvents and process or instance CPU or GPU counters from Perf. Collect session lock and unlock, logon ID, and trusted input-idle value; track by process unique key rather than name."),("在一至十五分钟活动转换窗口计算资源负载在活动后下降、空闲后恢复的重复序列，并在 24 小时聚合累计用量、矿池/代理输出及 owner。至少两次闭环、未经批准消费者和实际输出提升置信；只有固定夜间计划或低上限不满足。","Over one-to-fifteen-minute activity transitions, calculate repeated load decline after activity and resumption after idle. Aggregate total usage, pool or proxy output, and owner over 24 hours. At least two loops, an unapproved consumer, and actual output raise confidence; fixed nighttime schedules or low caps alone do not qualify.")),[req("endpoint-process-lineage",B("端点消费者进程谱系","Endpoint consumer process lineage"),"DeviceProcessEvents",["timestamp","device.id","process.unique.id","process.name","process.command.line","account.sid","initiating.process.unique.id","report.id"]),req("endpoint-network-flow",B("进程关联网络流","Process-linked network flow"),"DeviceNetworkEvents",["timestamp","device.id","process.unique.id","remote.ip","remote.port","protocol","bytes.sent","bytes.received"]),req("process-resource-counter",B("进程或实例资源计数","Process or instance resource counters"),"Azure Monitor Perf or equivalent",["time.generated","computer","object.name","counter.name","instance.name","counter.value"]),req("user-activity-state",B("用户与会话活动状态","User and session activity state"),None,["event.time","device.id","session.id","logon.id","activity.state","idle.seconds"])],[B("同一消费者在活动出现后降低资源并在空闲恢复","The same consumer lowers resource use after activity and resumes during idle"),B("重复闭环与未经批准矿池/收益网络或 owner 缺失相连","Repeated loops join an unapproved pool or profit network or missing owner")],B("活动转换一至十五分钟，累计用量与 owner 二十四小时，基线三十天。","Use one to fifteen minutes for activity transitions, 24 hours for total usage and owner, and a 30-day baseline."),["device.id","process.unique.id","session.id","activity.state","instance.name","remote.ip","event.time"],[B("批准的空闲维护、渲染、索引、备份、科学计算和 GPU 作业调度","Approved idle maintenance, rendering, indexing, backup, scientific computing, and GPU job scheduling")],[B("计数无进程维度、输入状态只限会话、进程注入、分布式低用量、矿池中继或未管理端点","Counters without process dimension, session-limited input state, process injection, distributed low usage, pool relay, or unmanaged endpoints")],P("维护批准的 idle job registry、owner、二进制签名和网络目的。阈值按设备角色与 GPU/CPU 能力调优，不全局放行签名工具；反馈闭环比固定百分比更重要。","Maintain an approved idle-job registry, owner, binary signature, and destinations. Tune by device role and GPU or CPU capability without globally allowing signed tools; the feedback loop matters more than one percentage."),["REF-000900","REF-000905","REF-000906","REF-000907","REF-000598","REF-000604"])

strategy(218,"provider-metered-resource-ownership",B("提供方计量事务与资源所有权关联","Provider-Metered Transaction and Resource-Ownership Correlation"),B("连接云或消息提供方成功交易、调用主体、目标、用量和 owner，发现主机外的未授权资源消耗。","Join successful cloud or messaging-provider transactions, caller, target, usage, and owner to find unauthorized consumption outside hosts."),PP(("策略覆盖父级托管服务路径与提供方代理子项，分别用 Bedrock 和 Twilio Analytic 展示不同真实字段。两者共享确认门槛：提供方成功执行/计量、受害账户承担资源结果、主体/入口无法映射批准用途。成本告警只作延迟支持。","This strategy covers the parent managed-service path and provider-brokered child and uses distinct Bedrock and Twilio analytics with real fields. Both share the confirmation gate: successful provider execution or metering, resource outcome on the victim account, and a principal or entry that cannot map to approved purpose. Cost alerts are delayed support only.")),["NJT-0189","NJS-0189-002"],["NJA-000268","NJA-000269"],["REF-000901","REF-000902","REF-000903","REF-000904","REF-000908","REF-000909","REF-000524"])
analytic(268,"bedrock-owner-metered-use","DET-000218",B("Bedrock 主体—模型—令牌计量分析","Bedrock Principal–Model–Token Metering Analytic"),B("输出新来源或未归属主体的成功模型调用、令牌用量和成本范围。","Emit successful model calls, token use, and cost scope from new origins or unowned principals."),["IaaS"],PP(("启用每区域 Bedrock invocation logging，采集 timestamp、accountId、region、requestId、operation、modelId、identity.arn、requestMetadata、input/output token。按 request/principal/time 与 CloudTrail 的 eventName、ARN/access key、source IP、user-agent、model、error 和 eventID 连接，并保留此前日志配置查询和服务探测。","Enable per-Region Bedrock invocation logging and collect timestamp, accountId, region, requestId, operation, modelId, identity ARN, requestMetadata, and input/output tokens. Join by request, principal, and time to CloudTrail eventName, ARN or access key, source IP, user-agent, model, error, and eventID and preserve preceding logging-configuration queries and service probes."),("按主体、应用/profile、模型和区域在十五分钟与 24 小时聚合调用/token，比较批准主体—来源—agent—模型组合与预算。成功调用和 token 证明消费；ValidationException 仅为侦察。Cost Anomaly 在后续关联根因而不替代交易。","Aggregate calls and tokens by principal, application or profile, model, and Region over fifteen minutes and 24 hours and compare approved principal-source-agent-model tuples and budgets. Successful calls and tokens establish consumption; ValidationException is reconnaissance only. Cost Anomaly later joins root cause without replacing transactions.")),[req("bedrock-invocation-log",B("Bedrock 模型调用日志","Bedrock model invocation log"),"Model invocation logging",["timestamp","account.id","aws.region","request.id","operation","model.id","identity.arn","request.metadata","input.token.count","output.token.count"]),req("cloudtrail-service-call",B("CloudTrail 服务调用","CloudTrail service calls"),"CloudTrail",["event.time","event.name","user.identity.arn","access.key.id","source.ip","user.agent","aws.region","request.id","model.id","error.code","event.id"]),req("resource-owner-budget",B("服务 owner 与预算基线","Service owner and budget baseline"),None,["account.id","application.id","owner.id","principal.arn","model.id","allowed.region","daily.token.budget","approval.id"])],[B("新来源或反向代理 user-agent 的成功高令牌调用","Successful high-token calls from a new origin or reverse-proxy user-agent"),B("未登记 owner 的主体、模型或区域持续产生计量用量","An unowned principal, model, or Region creates sustained metered usage")],B("CloudTrail 到调用日志正负五分钟，请求 burst 十五分钟，owner/成本二十四小时，基线三十天。","Use plus or minus five minutes from CloudTrail to invocation, fifteen minutes for bursts, 24 hours for owner and cost, and a 30-day baseline."),["account.id","aws.region","identity.arn","access.key.id","source.ip","user.agent","request.id","model.id"],[B("新 AI 应用、负载测试、批推理、跨区故障转移、模型迁移、共享开发角色和批准代理","New AI app, load test, batch inference, cross-Region failover, model migration, shared developer role, and approved proxy")],[B("调用日志默认未启用、端点不支持、共享角色、成本延迟、跨账户代理或批准高流量应用内滥用","Invocation logging disabled by default, unsupported endpoint, shared role, delayed cost, cross-account proxy, or abuse inside an approved high-volume app")],P("要求每应用 identity/profile/request metadata、短期角色、owner、允许来源/agent 和分主体/模型预算。不得全局抑制共享生产角色；缺详细日志时用 Invocations/InputTokenCount/OutputTokenCount 总量并标记归因丢失。","Require per-app identity, profile or request metadata, short-lived roles, owner, allowed origin and agent, and per-principal/model budgets. Never globally suppress a shared production role. When detailed logs are absent, use Invocations and token totals while marking attribution loss."),["REF-000901","REF-000903","REF-000904","REF-000908","REF-000524"])
analytic(269,"twilio-verify-metered-fraud","DET-000218",B("Twilio Verify 入口—短信交易—转换分析","Twilio Verify Entry–SMS Transaction–Conversion Analytic"),B("输出公共验证入口驱动的异常计费短信、目标前缀和低转换结果。","Emit abnormal billable messages, destination prefixes, and low conversion driven by a public verification entry."),["SaaS"],PP(("连接公共 OTP/验证请求日志的时间、request ID、source IP、user-agent、账户/设备、endpoint 与目的号码到 Twilio Verify sid、account/service SID、to、channel、conversionStatus 和干预/状态；按 E.164 得到国家，并在有对应产品日志时加入价格/消息状态。","Join public OTP or verification request time, request ID, source IP, user-agent, account or device, endpoint, and destination to Twilio Verify sid, account and service SID, to, channel, conversionStatus, and intervention or status; derive country from E.164 and add price or message status where the corresponding product log provides it."),("在五分钟滚动窗口和 24 小时成本范围比较请求率、不同号码、连续/高价前缀、低转换率、source-to-destination fan-out 和 provider blocks。没有 provider 交易是应用滥用企图；完成/计量发送才确认资源消耗。","Over a five-minute rolling window and 24-hour cost horizon, compare request rate, distinct numbers, sequential or high-cost prefixes, low conversion, source-to-destination fan-out, and provider blocks. An application request without a provider transaction is an abuse attempt; completed or metered sends confirm consumption.")),[req("verification-entry-log",B("公共验证入口日志","Public verification-entry log"),None,["event.time","request.id","source.ip","user.agent","account.id","device.id","endpoint.id","destination.number"]),req("twilio-verify-attempt",B("Twilio Verify 交易","Twilio Verify transactions"),"Twilio Verify Logs",["sid","account.sid","service.sid","date.created","date.updated","destination.number","channel","conversion.status","transaction.status","intervention.status"]),req("message-cost-outcome",B("短信成本与投递结果","Message cost and delivery outcome"),None,["sid","destination.country","price.amount","price.currency","delivery.status","campaign.id"])],[B("公共入口在短窗驱动高价/连续号码的大量已发送交易","A public entry drives many sent transactions to high-cost or sequential numbers in a short window"),B("高 fan-out 和低转换伴随提供方 fraud intervention 或成本异常","High fan-out and low conversion co-occur with provider fraud intervention or cost anomaly")],B("入口到 provider 两分钟，滥用 burst 五分钟，转换/成本二十四小时。","Use two minutes from entry to provider, five minutes for abuse bursts, and 24 hours for conversion and cost."),["application.id","endpoint.id","source.ip","device.id","request.id","service.sid","destination.country","event.time"],[B("客户登录峰值、产品发布、事件驱动重认证、旅行、QA/负载测试和运营误用 Verify","Customer sign-in peaks, product launch, incident-driven reauthentication, travel, QA or load tests, and operational misuse of Verify")],[B("无入口到 Verify 映射、CDN 丢失来源、分布式 bot、provider 延迟、跨国家号码或其他 provider 字段不同","Absent entry-to-Verify mapping, source lost behind CDN, distributed bots, provider delay, numbers across countries, or different fields from another provider")],P("按 source/device/account 和 destination prefix 限速，维护 endpoint 的转换与国家成本基线；不对白名单公共入口取消转换分析。只有 provider 交易成功才确认消耗。","Rate-limit by source, device, account, and destination prefix and maintain conversion and country-cost baselines per endpoint. Do not remove conversion analysis for an allowlisted public entry. Confirm consumption only on successful provider transactions."),["REF-000902","REF-000909"])


def measure(key, name, description, control_type):
    return {"key":key,"name":name,"description":description,"control_type":control_type}
def application(target, use, effect, limits):
    return {"target_ref":target,"use":use,"expected_effect":effect,"limitations":limits}

write("mitigations/MIT-000194-critical-business-service-control-resilience.yaml", {
 "schema_version":"2.0.0","type":"mitigation","id":"MIT-000194","name":B("关键业务服务控制与可用性韧性","Critical Business-Service Control and Availability Resilience"),"summary":B("限制停止权限、独立验证业务健康并提供快速恢复或故障转移，降低有序恶意停用的影响。","Restrict stop authority, validate business health independently, and provide rapid restart or failover to reduce orderly malicious disablement."),
 "description":PP(("此控制治理谁能停止关键业务服务、停止是否有审批、终态是否与外部健康一致以及如何恢复。它不依赖阻止合法管理接口，而以最小 SERVICE_STOP、不同权审批、业务探针和经过演练的启动/故障转移路径区分维护与攻击。","This control governs who can stop critical business services, whether stopping is approved, whether terminal state matches external health, and how service is restored. It does not prohibit legitimate management interfaces and instead uses least SERVICE_STOP, differently authorized approval, business probes, and exercised restart or failover to distinguish maintenance from attack.")),"domains":["enterprise"],
 "measures":[measure("least-stop-authority",B("最小服务停止权限","Least Service-Stop Authority"),P("为关键业务服务收紧 DACL/RBAC 与远程管理权限，只向有明确职责和短期审批的身份授予停止、禁用和依赖控制。","Tighten DACL or RBAC and remote-management rights for critical services, granting stop, disable, and dependency control only to identities with a defined role and time-bound approval."),"preventive"),measure("independent-health-approval",B("独立健康与审批校验","Independent Health and Approval Validation"),P("从与服务控制面不同权的探针验证业务可用性，将每次停止连接到 owner、变更单、调用者和终态，并对无审批的正常终态告警。","Validate business availability from a probe authorized separately from the service control plane and join every stop to owner, change record, caller, and terminal state, alerting on an ordinary terminal state without approval."),"detective-support"),measure("tested-restart-failover",B("经过演练的启动与故障转移","Tested Restart and Failover"),P("维护依赖顺序、已知良好配置、快速重启与集群故障转移流程，定期验证停止后能恢复合法会话和数据一致性。","Maintain dependency order, known-good configuration, rapid restart, and cluster failover procedures and regularly verify legitimate sessions and data consistency after a stop."),"containment")],
 "applications":[application("NJT-0185",P("对数据库、消息、Web 和虚拟化业务服务执行最小停止权限、双人或工单审批、外部健康探测和启动/故障转移演练；无审批控制与健康失败同时出现时隔离调用者。","Apply least stop authority, dual or ticketed approval, external health probes, and restart or failover exercises to database, messaging, Web, and virtualization services; isolate the caller when unapproved control and health failure co-occur."),P("攻击者更难借标准控制路径产生看似普通的 stopped 终态，服务中断范围和持续时间下降，控制主体保持可追溯。","It becomes harder to use a standard control path for an ordinary-looking stopped state; outage scope and duration fall and the controller remains attributable."),P("高权被盗、集群共同管理面受陷或合法紧急维护会绕过/触发控制；快速自动重启可能与攻击者反复停止形成循环并放大风险。","Stolen high privilege, compromise of a shared cluster plane, or legitimate emergency maintenance can bypass or trigger controls. Rapid automatic restart can loop against repeated attacker stops and amplify risk."))],"evidence_refs":["REF-000336","REF-000866","REF-000867","REF-000871"],"lifecycle":life()})

write("mitigations/MIT-000195-recovery-control-authority-immutable-vault.yaml", {
 "schema_version":"2.0.0","type":"mitigation","id":"MIT-000195","name":B("恢复控制权限与不可变保管库治理","Recovery-Control Authority and Immutable-Vault Governance"),"summary":B("把恢复删除和生命周期权限与生产分离，并用不可变保管库、最低保留和完整恢复演练保护可恢复性。","Separate recovery deletion and lifecycle authority from production and protect recoverability with immutable vaults, retention floors, and full restore exercises."),
 "description":PP(("此控制保护恢复控制面而不仅是保存一份备份。删除、生命周期、计划、锁和密钥权限由不同权 break-glass 身份管理；关键恢复点进入经验证的 compliance/WORM 保留和隔离副本，并通过资源—恢复点—密钥—依赖映射与全量恢复演练验证。","This control protects the recovery control plane rather than merely retaining one backup. Delete, lifecycle, plan, lock, and key rights are managed by differently authorized break-glass identities. Critical points enter validated compliance or WORM retention and isolated copies and are verified through resource-to-point-to-key-to-dependency maps and full restores.")),"domains":["enterprise"],
 "measures":[measure("separate-recovery-administration",B("恢复管理与生产权限分离","Separate Recovery Administration"),P("将恢复删除、策略更新、锁变更和密钥权限从生产身份移出，要求抗钓鱼 MFA、短期 break-glass、双人审批和独立日志。","Move recovery deletion, policy update, lock change, and key rights away from production identities and require phishing-resistant MFA, time-bound break-glass, dual approval, and independent logs."),"preventive"),measure("immutable-retention-floor",B("不可变保留与最低期限","Immutable Retention and Minimum Duration"),P("在验证宽限期和保留边界后，对关键恢复点采用 compliance 模式或等价 WORM，并在策略层阻止保留期限低于工作负载要求。","After validating grace and retention bounds, use compliance mode or equivalent WORM for critical points and prevent policy retention below workload requirements."),"preventive"),measure("dependency-aware-restore-test",B("依赖感知完整恢复演练","Dependency-Aware Full Restore Test"),P("维护资源、恢复点、密钥、身份、网络和应用依赖映射，按 RPO/RTO 定期执行隔离环境的完整恢复。","Maintain mappings among resources, recovery points, keys, identities, network, and application dependencies and regularly perform full restoration in an isolated environment against RPO and RTO."),"governance")],
 "applications":[application("NJT-0186",P("保护本地卷影之外的独立副本和云恢复点，限制删除/禁用权限，对恢复状态下降实时告警，并用隔离演练确认实际恢复。","Protect independent copies and cloud recovery points beyond local shadows, restrict delete and disable rights, alert on recovery-state reduction, and confirm actual restoration through isolated exercises."),P("直接删除和服务停用的成功率下降，即使在线副本受损仍保留不同权恢复路径。","Direct deletion and service-disable success falls, and a differently authorized recovery path survives even if online copies are harmed."),P("本地卷影不是独立备份，同一身份域的副本可能同时受损；严格锁会增加成本并放大错误保留配置，演练也不维持当前生产可用性。","Local shadows are not independent backup, copies in the same identity domain can fail together, strict locks add cost and amplify retention mistakes, and exercises do not preserve current production availability.")),application("NJS-0186-001",P("对备份生命周期设置最低保留与批准 policy hash，使用 compliance Vault Lock 阻止 UpdateRecoveryPointLifecycle 缩短受保护点，并对任何计划/锁/连续规则变化预警。","Set retention floors and approved policy hashes for backup lifecycle, use compliance Vault Lock to prevent UpdateRecoveryPointLifecycle from shortening protected points, and alert on any plan, lock, or continuous-rule change."),P("恶意策略不能在宽限期后缩短已保护恢复点，配置变化在服务到期前暴露，保留链可追溯。","A malicious policy cannot shorten protected points after the grace period, configuration changes surface before service expiry, and retention lineage remains attributable."),P("已有点在加锁前的生命周期、产品特定连续备份语义和另一个未保护副本仍可能造成缺口；compliance 配置错误在宽限期后不可逆。","Existing point lifecycle before locking, product-specific continuous-backup semantics, and another unprotected copy can still create gaps; a compliance configuration error becomes irreversible after grace."))],"evidence_refs":["REF-000877","REF-000878","REF-000879","REF-000880"],"lifecycle":life()})

write("mitigations/MIT-000196-display-publication-resolution-integrity.yaml", {
 "schema_version":"2.0.0","type":"mitigation","id":"MIT-000196","name":B("展示发布与解析权威完整性","Display Publication and Resolution Authority Integrity"),"summary":B("分离内容发布与域名权威，保护绑定并从独立观察点验证实际展示，以阻止或快速恢复篡改。","Separate publication from domain authority, protect bindings, and validate actual display from independent vantages to prevent or rapidly recover defacement."),
 "description":PP(("此控制同时保护批准内容、标识到源的绑定和实际人类可见结果。内容、DNS/注册、证书与恢复权限分离；高风险记录和发布需强身份与审批；批准内容/RRset 版本化，并从不共用生产解析或源站的观察点验证输出。","This control protects approved content, identifier-to-source binding, and actual human-visible output together. Content, DNS or registration, certificate, and recovery authorities are separated; high-risk records and releases require strong identity and approval; approved content and RRsets are versioned and output is verified from vantages independent of production resolution and origin.")),"domains":["enterprise"],
 "measures":[measure("segregated-publish-dns-authority",B("发布与域名权限分离","Separate Publication and Domain Authority"),P("为注册商、权威 DNS、CMS 与证书使用抗钓鱼 MFA、最小权限、独立恢复渠道和双人高风险变更。","Use phishing-resistant MFA, least privilege, independent recovery channels, and dual approval for high-risk changes at registrar, authoritative DNS, CMS, and certificate systems."),"preventive"),measure("domain-lock-signed-resolution",B("域名锁与签名解析","Domain Locks and Signed Resolution"),P("启用适用 registrar/registry 更新与转移锁，正确部署 DNSSEC 并监测验证失败；锁解除和 DS/NS 变化需带外复核。","Enable applicable registrar and registry update or transfer locks, deploy DNSSEC correctly and monitor validation failure; review lock removal and DS or NS changes out of band."),"preventive"),measure("versioned-display-assurance",B("版本化展示状态与独立验证","Versioned Display State and Independent Assurance"),P("保存批准内容、UI 配置、RRset 和发布清单，从多个独立观察点核对实际展示；变更通知发送到不同域和身份。","Retain approved content, UI configuration, RRsets, and release manifests and verify actual display from multiple independent vantages; send change notifications to a different domain and identity."),"detective-support"),measure("evidence-preserving-rollback",B("保全证据的回滚","Evidence-Preserving Rollback"),P("篡改时先保存注册/DNS、证书、页面和发布证据，再恢复账户、记录和已知良好内容并验证解析收敛。","On defacement preserve registrar and DNS, certificate, page, and release evidence before restoring accounts, records, and known-good content and validating resolution convergence."),"containment")],
 "applications":[application("NJT-0187",P("为网站、入口、banner 与桌面展示登记 owner、批准 release、允许变体、实际结果和恢复版本，分离高权限并用输出而非源文件 alone 验证发布。","Register owner, approved release, allowed variants, actual output, and recovery version for websites, portals, banners, and desktops; separate privilege and validate publication by output rather than source files alone."),P("未经授权内容更改更难发生且能快速定位到源或绑定平面，恢复时间和受众暴露下降。","Unauthorized display changes become harder and can be quickly localized to source or binding planes, reducing recovery time and audience exposure."),P("被盗批准身份或同步篡改审批仍可形成完整但恶意链；备份恢复内容不能修补入侵入口或消除品牌影响。","A stolen approved identity or co-tampered approval can form a complete malicious chain; content restoration does not repair entry or remove brand impact.")),application("NJS-0187-001",P("对组织域启用注册/registry lock、抗钓鱼 MFA、独立恢复联系和双人 DNS 变更；保留前后 RRset、部署 DNSSEC，并从多个解析器抓取实际页面与规范源比较。","Use registrar or registry locks, phishing-resistant MFA, independent recovery contacts, and dual DNS changes for organization domains; retain before and after RRsets, deploy DNSSEC, and retrieve actual pages from multiple resolvers for canonical comparison."),P("标识到源的未授权替换被阻止或快速暴露，干净源站不再被误当作无影响证据。","Unauthorized identifier-to-source replacement is blocked or rapidly exposed, and a clean origin is no longer mistaken for evidence of no impact."),P("DNSSEC 不能阻止已控制权威签名的攻击者，本地解析或客户端路径劫持可能在权威区外发生；缓存与严格锁会增加恢复复杂度。","DNSSEC cannot stop an attacker controlling authoritative signing, and local resolver or client-path hijack can occur outside the authoritative zone; caches and strict locks complicate recovery."))],"evidence_refs":["REF-000884","REF-000887","REF-000888","REF-000889","REF-000890"],"lifecycle":life()})

write("mitigations/MIT-000197-resource-ownership-residual-capacity-control.yaml", {
 "schema_version":"2.0.0","type":"mitigation","id":"MIT-000197","name":B("资源所有权与剩余容量消费控制","Resource Ownership and Residual-Capacity Consumption Control"),"summary":B("为计算和网络消费者绑定 owner、用途和限额，并控制端点恶意消费者与反馈门控，限制资源劫持收益。","Bind compute and network consumers to owner, purpose, and limits and control endpoint malicious consumers and feedback gating to constrain Resource Hijacking yield."),
 "description":PP(("此控制把资源使用从“谁能启动进程”扩展到“谁拥有用量、预算和输出”。每个主机、容器、作业和凭据记录 owner、批准用途、配额和到期；独立计量与应用控制限制未知消费者，并对反复跟随用户活动启停的 ownerless 进程响应。","This control extends resource use from who can start a process to who owns usage, budget, and output. Each host, container, job, and credential has an owner, approved purpose, quota, and expiry. Independent metering and application control constrain unknown consumers and respond to ownerless processes that repeatedly follow user activity.")),"domains":["enterprise"],
 "measures":[measure("resource-owner-purpose-budget",B("资源 owner、用途与预算","Resource Owner, Purpose, and Budget"),P("为计算、网络与作业建立 owner、批准用途、区域、配额、预算和到期，并拒绝无 owner 的新消费者或配额提升。","Assign owner, approved purpose, Region, quota, budget, and expiry to compute, network, and jobs and deny unowned consumers or quota increases."),"governance"),measure("independent-resource-metering",B("独立资源计量与遏制","Independent Resource Metering and Containment"),P("从与工作负载不同权的平台采集 CPU/GPU/网络和成本，在 ownerless 用量越过调优界限时限制或隔离消费者。","Collect CPU, GPU, network, and cost from a plane authorized separately from the workload and limit or isolate consumers when ownerless usage exceeds tuned bounds."),"containment"),measure("endpoint-consumer-control",B("端点消费者执行与反馈控制","Endpoint Consumer Execution and Feedback Control"),P("使用应用控制、EDR、受保护排除项、任务/服务完整性、矿池/代理出口限制和进程/容器资源上限，维护批准 idle job 清单。","Use application control, EDR, protected exclusions, task or service integrity, pool or proxy egress limits, and process or container resource caps and maintain an approved idle-job registry."),"preventive")],
 "applications":[application("NJT-0189",P("为端点、容器、云工作负载和网络消费者登记 owner 与预算，拒绝未归属服务启用和配额变化，并把性能、网络和费用关联到任务输出。","Register owner and budget for endpoint, container, cloud-workload, and network consumers; deny unowned service enablement and quota changes and join performance, network, and cost to task output."),P("未授权消费者收益受限，无 owner 的资源消耗变为可处置违规，费用与配额损失范围下降。","Unauthorized-consumer yield is bounded, unowned consumption becomes actionable, and cost or quota loss is limited."),P("低速窃用可留在上限内，计费延迟，被盗批准 owner 可能看似正常，严格限额也会损害合法 burst。","Low-rate theft can remain under limits, billing is delayed, a stolen approved owner can appear normal, and strict caps can harm legitimate bursts.")),application("NJS-0189-001",P("对交互端限制未知消费者、保护任务/服务与 Defender 排除项，设置进程或容器资源上限，阻断已知矿池/代理出口，并调查随活动状态反复启停的进程。","On interactive endpoints restrict unknown consumers, protect tasks or services and Defender exclusions, set process or container caps, block known pool or proxy egress, and investigate processes repeatedly starting or stopping with activity state."),P("消费者难以在空闲期长期积累收益，即使门控仍存在也被 owner、应用控制和资源上限限制，并留下清晰关联。","Consumers have less ability to accumulate yield during idle; even with gating, owner, application control, and resource caps constrain them and leave clearer correlation."),P("受信签名工具或注入可绕过简单路径规则，资源上限不证明恶意，矿池可用中继，合法维护也会使用空闲时间。","Trusted signed tools or injection can bypass simple path rules, caps do not prove malice, pools can use relays, and legitimate maintenance uses idle time."))],"evidence_refs":["REF-000900","REF-000905","REF-000906","REF-000907","REF-000598","REF-000604"],"lifecycle":life()})

write("mitigations/MIT-000198-metered-service-transaction-admission.yaml", {
 "schema_version":"2.0.0","type":"mitigation","id":"MIT-000198","name":B("计量服务最小权限与事务准入","Metered-Service Least Privilege and Transaction Admission"),"summary":B("用分应用短期身份、服务准入、事务限额和 bot/目标风险控制阻止公共入口或被盗凭据转化为受害方计费任务。","Use per-app short-lived identities, service admission, transaction limits, and bot or destination-risk controls to stop public entries or stolen credentials becoming victim-billed work."),
 "description":PP(("此控制保护提供方执行和计量的资源。组织只启用所需模型、消息和区域，以分应用身份和 owner metadata 连接交易，开启提供方日志并按主体、模型、消息、目标和费用设界。公共表单还需服务端速率、设备/账户和号码风险以及 bot challenge。","This control protects provider-executed and metered resources. Organizations enable only required models, messaging, and Regions, join transactions through per-app identities and owner metadata, enable provider logs, and bound by principal, model, message, target, and cost. Public forms also need server-side rate, device or account and number risk, and bot challenge.")),"domains":["enterprise"],
 "measures":[measure("per-app-short-lived-identity",B("分应用短期身份与服务准入","Per-App Short-Lived Identity and Service Admission"),P("用短期角色或 key、最小模型/消息权限、允许来源与区域，只为有 owner 的应用启用计量服务；未使用服务默认拒绝。","Use short-lived roles or keys, minimal model or messaging rights, allowed origins and Regions, and enable metered services only for owned applications; deny unused services by default."),"preventive"),measure("transaction-quota-provider-logs",B("事务限额与提供方日志","Transaction Quotas and Provider Logs"),P("开启每区域调用/交易日志，要求 application profile 或 request owner metadata，并按主体、模型、token、消息、目标和预算设限与告警。","Enable per-Region invocation or transaction logs, require application profiles or request owner metadata, and apply limits and alerts by principal, model, token, message, target, and budget."),"detective-support"),measure("public-entry-fraud-admission",B("公共入口欺诈准入","Public-Entry Fraud Admission"),P("对 OTP/验证入口实施服务端速率、设备和账户约束、号码/国家风险、provider Fraud Guard 和 CAPTCHA/等价 bot challenge，并保留入口到 provider 的交易 ID。","Apply server-side rate, device and account controls, number or country risk, provider Fraud Guard, and CAPTCHA or equivalent bot challenge to OTP or verification entries, preserving entry-to-provider transaction IDs."),"preventive")],
 "applications":[application("NJS-0189-002",P("对 Bedrock/托管 AI 使用分应用角色、模型与区域 allowlist、调用日志和 token/预算；对 SMS/验证入口连接应用请求与 provider 交易并按 source/device/account/destination 限速和风控。","For Bedrock or hosted AI use per-app roles, model and Region allowlists, invocation logging, and token or budget controls. For SMS or verification entries join application requests to provider transactions and rate-limit and risk-screen by source, device, account, and destination."),P("广泛共享凭据或公共表单更难无声转换为受害方付费工作，剩余 token、消息和费用被主体级界限控制。","Broad shared credentials or public forms have less ability to silently become victim-paid work, and residual tokens, messages, and cost are bounded per principal."),P("分布式仿人流量可绕过挑战，被盗批准应用可能留在正常量内，详细模型日志可能含敏感 prompt，预算告警可能晚于花费。","Distributed human-like traffic can bypass challenges, a compromised approved app may remain within normal volume, detailed model logs can contain sensitive prompts, and budget alerts can lag spending.")),application("NJT-0189",P("对托管服务资源建立 owner、允许服务/区域和主体级预算，把成本异常回连真实交易；本应用补充 MIT-000197 的端点/工作负载资源控制。","Establish owners, allowed services or Regions, and principal-level budgets for managed-service resources and connect cost anomalies to transactions; this complements endpoint and workload controls in MIT-000197."),P("提供方消费被纳入统一资源所有权和限额，主机外用量不再只在月底账单暴露。","Provider consumption enters unified ownership and limits, so off-host use is not exposed only at month-end billing."),P("不同提供方字段和控制不可互换，成本数据仍会延迟，未覆盖的第三方应用可能没有交易级日志。","Provider fields and controls are not interchangeable, cost data remains delayed, and uncovered third-party apps may lack transaction-level logs."))],"evidence_refs":["REF-000901","REF-000902","REF-000903","REF-000904","REF-000908","REF-000909"],"lifecycle":life()})

# Extend existing mitigations only where the control identity is unchanged.
def extend_mitigation(mit_id, refs, new_apps, version):
    path = next((ROOT / "mitigations").glob(f"{mit_id}-*.yaml"))
    value = yaml.safe_load(path.read_text(encoding="utf-8"))
    existing = {item["target_ref"] for item in value["applications"]}
    value["applications"].extend(item for item in new_apps if item["target_ref"] not in existing)
    value["evidence_refs"] = list(dict.fromkeys(value["evidence_refs"] + refs))
    value["lifecycle"]["modified"] = TODAY
    value["lifecycle"]["version"] = version
    path.write_text(yaml.safe_dump(value, allow_unicode=True, sort_keys=False, width=112), encoding="utf-8")

extend_mitigation("MIT-000158", ["REF-000877","REF-000878","REF-000879","REF-000880"], [
 application("NJT-0186",P("在生产写入权限之外保留至少一份受版本或不可变控制保护的恢复副本，并定期从该副本恢复真实工作负载。","Keep at least one versioned or immutable recovery copy outside production-writer authority and regularly restore the real workload from it."),P("本地卷影或在线恢复点被删除时仍保留可用恢复路径，并能从演练验证依赖。","A usable recovery path survives deletion of local shadows or online recovery points and dependencies are validated by exercises."),P("同一身份或控制面的副本不独立，定期演练不能维持当前生产可用性，未覆盖资产仍会失去恢复。","Copies in the same identity or control plane are not independent, periodic exercises do not preserve current production availability, and uncovered assets can still lose recovery."))], "0.4.0")

extend_mitigation("MIT-000077", ["REF-000891","REF-000892","REF-000894","REF-000895","REF-000897"], [
 application("NJT-0188",P("对平台与组件固件启用硬件写保护、签名 capsule 和最低版本策略，以不同权启动度量和外部 BMC 观察完整覆盖；保存匹配硬件 GUID 的可信映像、离线读回与独立恢复根。","Enable hardware write protection, signed capsules, and minimum-version policy for platform and component firmware, measure complete coverage through differently authorized boot attestation and external BMC observation, and retain trusted images matched to hardware GUID, offline readback, and an independent recovery root."),P("未经授权写入更难提交，固件消费失败可在 OS 缺席时仍由外部面识别，可信恢复减少永久 brick 和根因丢失。","Unauthorized writes become harder to commit, firmware-consumption failure remains identifiable externally when the OS is absent, and trusted recovery reduces permanent bricking and root-cause loss."),P("旧设备可能无写保护或完整测量，BMC 可能同权受陷，恢复会停机并改变证据，错误的已知良好映像可造成二次损害。","Legacy devices may lack write protection or complete measurement, a similarly authorized BMC may be compromised, recovery causes outage and changes evidence, and a wrong known-good image can create further damage."))], "1.1.0")
